#!/bin/sh
# PostgreSQL Physical Replication Control / Planned Switchover
# Supported PostgreSQL major versions: 12 through 18
#
# Design constraints
#   - POSIX /bin/sh compatible
#   - No Python, jq, yq, expect, Perl modules, repmgr, Patroni, pg_auto_failover
#   - No package installation
#   - No hard-coded PGDATA, port, socket, host, service, PostgreSQL user, or binary path
#   - PostgreSQL binaries + standard base OS utilities only
#
# Public mode
#   --check-only : run Planned Switchover prechecks without changing PostgreSQL state
#
# Exit codes for --check-only
#   0 : all required checks passed (warnings may exist)
#   1 : validation failed or a required manual check remains unresolved
#   2 : input / usage error
#   3 : remote SSH connection failure
#
# IMPORTANT
#   - This script does NOT perform automatic failover.
#   - Planned Switchover requires the current Primary to be available.

set -u
umask 077

SCRIPT_VERSION="0.1.16"
SCRIPT_PATH=$0
TAB=$(printf '\t')
CHECK_ONLY=0
INTERNAL_MODE=0

EX_OK=0
EX_VALIDATION=1
EX_USAGE=2
EX_REMOTE=3

# Safety-policy bounds, not environment-specific PostgreSQL values.
TIMEOUT_MIN=1
TIMEOUT_MAX=3600
SSH_CONNECT_TIMEOUT=10

TMP_FILES=""
CURRENT_PHASE="initial"
SWITCHOVER_PRIMARY_STOPPED=0
SWITCHOVER_PROMOTED=0
SWITCHOVER_CONFIG_CHANGED=0
SWITCHOVER_ROLLBACK_VERIFIED=0

PGDATA="${PGDATA:-}"
PG_BINDIR="${PG_BINDIR:-}"
PG_START_OPTIONS="${PG_START_OPTIONS:-}"
PGPORT="${PGPORT:-}"
PGUSER_LOCAL="${PGUSER:-}"
DB_NAME=""
PSQL_BIN=""
PG_CTL_BIN=""
PG_CONTROLDATA_BIN=""
POSTMASTER_PID=""
POSTMASTER_OPTIONS=""
SOCKET_DIR=""
PG_MAJOR=""
PG_VERSION_NUM=""
SYSTEM_IDENTIFIER=""
LOCAL_ROLE=""
CONFIG_FILE=""
AUTO_CONF=""
STATE_DIR=""
STATE_KEY=""
CANONICAL_PGDATA=""

REMOTE_TRANSPORT=""
REMOTE_SSH_HOST=""
REMOTE_SSH_USER=""
REMOTE_TARGET=""
REMOTE_PGDATA=""
REMOTE_PORT=""
REMOTE_VERSION_NUM=""
REMOTE_MAJOR=""
REMOTE_SYSTEM_IDENTIFIER=""
REMOTE_ROLE=""
REMOTE_TOPOLOGY_ROLE=""
REMOTE_DOWNSTREAM_COUNT="0"
REMOTE_RECOVERY_TARGET_TIMELINE=""
REMOTE_RECEIVER_SLOT=""
REMOTE_RECEIVER_STATUS=""
REMOTE_SENDER_HOST=""
REMOTE_SENDER_PORT=""
REMOTE_LOCK_TOKEN=""
REMOTE_LOCK_HELD=0

LOCAL_LOCK_DIR=""
LOCAL_LOCK_HELD=0

REPORT_FILE=""
REPORT_ACTIVE=0
RESULT_FILE=""
RESULTS_LIST_FILE=""
RESULT_PASSED=0
RESULT_WARNING=0
RESULT_FAILED=0
RESULT_MANUAL=0
FINAL_EXIT_OVERRIDE=""

say() { printf '%s\n' "$*"; }
info() { printf '[INFO] %s\n' "$*"; }
warn() { printf '[WARN] %s\n' "$*" >&2; }
error() { printf '[ERROR] %s\n' "$*" >&2; }

section() {
    say ""
    say "==============================================================================="; printf '[ %s ]\n' "$1"; [ -n "${2:-}" ] && printf '  %s\n' "$2"; say "===============================================================================";
}

kv() { printf '  %-34s : %s\n' "$1" "${2:-}"; }

usage() {
    say "Usage: $0 [--check-only]"
    say ""
    say "  --check-only"
    say "     Planned Switchover에 필요한 검증만 수행합니다."
    say "     PostgreSQL 설정 변경, 서버 종료, promotion은 수행하지 않습니다."
}

sanitize_report_detail() {
    srd=$1
    case "$srd" in *password=*|*PASSWORD=*|*primary_conninfo=*|*PRIMARY_CONNINFO=*) printf '%s\n' "sensitive connection detail redacted" ;; *) printf '%s\n' "$srd" ;; esac
}
record_result() {
    rr_status=$1; rr_item=$2; rr_detail=$(sanitize_report_detail "${3:-}")
    case "$rr_status" in PASSED) RESULT_PASSED=$((RESULT_PASSED+1));; WARNING) RESULT_WARNING=$((RESULT_WARNING+1));; FAILED) RESULT_FAILED=$((RESULT_FAILED+1));; "MANUAL CHECK") RESULT_MANUAL=$((RESULT_MANUAL+1));; *) return 1;; esac
    printf '%-12s | %-36s | %s\n' "$rr_status" "$rr_item" "$rr_detail"
    [ -n "$RESULTS_LIST_FILE" ] || RESULTS_LIST_FILE=$(mktemp_safe 2>/dev/null || echo "")
    [ -n "$RESULTS_LIST_FILE" ] && printf '%-12s | %-36s | %s\n' "$rr_status" "$rr_item" "$rr_detail" >> "$RESULTS_LIST_FILE"
    [ "$REPORT_ACTIVE" -eq 1 ] && [ -n "$REPORT_FILE" ] && printf '%-12s | %-36s | %s\n' "$rr_status" "$rr_item" "$rr_detail" >> "$REPORT_FILE"
}
show_result_summary() {
    section "Validation Summary" "각 검증 항목을 PASSED, WARNING, FAILED, MANUAL CHECK로 요약합니다."
    [ -n "$RESULTS_LIST_FILE" ] && [ -f "$RESULTS_LIST_FILE" ] && cat "$RESULTS_LIST_FILE"
    kv PASSED "$RESULT_PASSED"; kv WARNING "$RESULT_WARNING"; kv FAILED "$RESULT_FAILED"; kv "MANUAL CHECK" "$RESULT_MANUAL"
}
report_init() {
    [ "$CHECK_ONLY" -eq 1 ] || return 0
    ri_now=$(date '+%Y%m%d_%H%M%S' 2>/dev/null || echo unknown_time); ri_base=${PGROLE_REPORT_DIR:-${PWD:-.}}
    if [ ! -d "$ri_base" ] || [ ! -w "$ri_base" ]; then ri_base=${TMPDIR:-/tmp}; fi
    REPORT_FILE="$ri_base/postgresql_role_switch_check_${ri_now}_$$.txt"
    : > "$REPORT_FILE" || { error "Cannot create check result file under $ri_base"; REPORT_FILE=""; return 1; }
    chmod 600 "$REPORT_FILE" 2>/dev/null || true; REPORT_ACTIVE=1
    { printf 'PostgreSQL Planned Switchover --check-only Result\n'; printf 'script_version : %s\n' "$SCRIPT_VERSION"; printf 'executed_at    : %s\n' "$(date '+%Y-%m-%d %H:%M:%S %z' 2>/dev/null || echo unknown)"; printf '\nRESULTS\n'; } >> "$REPORT_FILE"
}
report_instance_metadata() {
    [ "$REPORT_ACTIVE" -eq 1 ] || return 0
    { printf '\nINSTANCE\n'; printf 'data_directory : %s\n' "$PGDATA"; printf 'port           : %s\n' "$PGPORT"; printf 'server_version : %s\n' "$PG_VERSION_NUM"; printf 'system_id      : %s\n' "$SYSTEM_IDENTIFIER"; printf 'topology       : %s\n' "$(current_topology_role 2>/dev/null || echo unknown)"; } >> "$REPORT_FILE"
}
report_finalize() {
    [ "$REPORT_ACTIVE" -eq 1 ] || return 0; [ -n "$REPORT_FILE" ] || return 0
    { printf '\nSUMMARY\n'; printf 'PASSED       : %s\n' "$RESULT_PASSED"; printf 'WARNING      : %s\n' "$RESULT_WARNING"; printf 'FAILED       : %s\n' "$RESULT_FAILED"; printf 'MANUAL CHECK : %s\n' "$RESULT_MANUAL"; } >> "$REPORT_FILE"
    REPORT_ACTIVE=0; RESULT_FILE=$REPORT_FILE
}
check_only_exit_code() { [ "$RESULT_FAILED" -gt 0 ] || [ "$RESULT_MANUAL" -gt 0 ] && return "$EX_VALIDATION"; return "$EX_OK"; }
fatal_validation() { error "$*"; [ "$CHECK_ONLY" -eq 1 ] && record_result FAILED Validation "$*" >/dev/null; FINAL_EXIT_OVERRIDE=$EX_VALIDATION; exit "$EX_VALIDATION"; }
fatal_usage() { error "$*"; usage >&2; FINAL_EXIT_OVERRIDE=$EX_USAGE; exit "$EX_USAGE"; }
fatal_remote() { error "$*"; [ "$CHECK_ONLY" -eq 1 ] && record_result FAILED "Remote SSH Connection" "$*" >/dev/null; FINAL_EXIT_OVERRIDE=$EX_REMOTE; exit "$EX_REMOTE"; }

mktemp_safe() {
    if command -v mktemp >/dev/null 2>&1; then t=$(mktemp "${TMPDIR:-/tmp}/pg-role-switch.XXXXXX") || return 1; else t="${TMPDIR:-/tmp}/pg-role-switch.$$.$(date +%s 2>/dev/null || echo 0)"; (umask 077; : > "$t") || return 1; fi
    TMP_FILES="${TMP_FILES}${TMP_FILES:+
}$t"; printf '%s\n' "$t"
}
cleanup_tmp() { printf '%s\n' "$TMP_FILES" | while IFS= read -r f; do [ -n "$f" ] && [ -f "$f" ] && rm -f "$f"; done; }
shell_quote() { printf "'%s'" "$(printf '%s' "$1" | sed "s/'/'\\\\''/g")"; }
release_local_lock() { [ "$LOCAL_LOCK_HELD" -eq 1 ] || return 0; [ -n "$LOCAL_LOCK_DIR" ] && [ -d "$LOCAL_LOCK_DIR" ] && { rm -f "$LOCAL_LOCK_DIR/pid" "$LOCAL_LOCK_DIR/data_directory" 2>/dev/null || true; rmdir "$LOCAL_LOCK_DIR" 2>/dev/null || true; }; LOCAL_LOCK_HELD=0; }
release_remote_lock() { [ "$REMOTE_LOCK_HELD" -eq 1 ] || return 0; if [ "$REMOTE_TRANSPORT" = ssh ]; then invoke_on_transport ssh "$REMOTE_TARGET" --remote-lock-release "$REMOTE_PGDATA" "$REMOTE_LOCK_TOKEN" >/dev/null 2>&1 || true; elif [ "$REMOTE_TRANSPORT" = local ]; then invoke_on_transport local local --remote-lock-release "$REMOTE_PGDATA" "$REMOTE_LOCK_TOKEN" >/dev/null 2>&1 || true; fi; REMOTE_LOCK_HELD=0; }

rollback_preconfigured_primary() {
    [ "$SWITCHOVER_CONFIG_CHANGED" -eq 1 ] || return 0; [ -n "${SWITCHOVER_RESTORE_FILE:-}" ] && [ -f "$SWITCHOVER_RESTORE_FILE" ] || return 1
    if psql_call_file "$SWITCHOVER_RESTORE_FILE" >/dev/null 2>&1; then
        [ "$PG_MAJOR" -ge 13 ] && psql_call "SELECT pg_reload_conf()" >/dev/null 2>&1 || true
        rb_now=$(psql_call "SELECT setting FROM pg_settings WHERE name='primary_conninfo'" 2>/dev/null | sed -n '1p') || rb_now="__ERROR__"
        rb_slot=$(psql_call "SELECT setting FROM pg_settings WHERE name='primary_slot_name'" 2>/dev/null | sed -n '1p') || rb_slot="__ERROR__"
        rb_tl=$(psql_call "SELECT setting FROM pg_settings WHERE name='recovery_target_timeline'" 2>/dev/null | sed -n '1p') || rb_tl="__ERROR__"
        if [ "$rb_now" = "${ROLLBACK_PRIMARY_CONNINFO:-}" ] && [ "$rb_slot" = "${ROLLBACK_PRIMARY_SLOT:-}" ] && [ "$rb_tl" = "${ROLLBACK_RECOVERY_TIMELINE:-}" ]; then SWITCHOVER_ROLLBACK_VERIFIED=1; rm -f "$SWITCHOVER_RESTORE_FILE" 2>/dev/null || true; SWITCHOVER_CONFIG_CHANGED=0; return 0; fi
    fi; return 1
}
handle_signal() {
    hs_name=$1; hs_code=$2; warn "Received $hs_name. Cleaning temporary state."
    if [ "$SWITCHOVER_CONFIG_CHANGED" -eq 1 ] && [ "$SWITCHOVER_PRIMARY_STOPPED" -eq 0 ]; then
        if rollback_preconfigured_primary; then warn "Staged PostgreSQL settings were rolled back and verified."; [ "$CHECK_ONLY" -eq 1 ] && record_result PASSED "Signal rollback" "staged settings restored and verified" >/dev/null; else warn "Could not verify rollback of staged PostgreSQL settings. Manual verification is required."; [ "$CHECK_ONLY" -eq 1 ] && record_result "MANUAL CHECK" "Signal rollback" "automatic rollback verification failed" >/dev/null; fi
    fi
    FINAL_EXIT_OVERRIDE=$hs_code; exit "$hs_code"
}
on_exit() {
    rc=$?; trap - EXIT HUP INT TERM
    if [ "$rc" -ne 0 ] && [ "$SWITCHOVER_CONFIG_CHANGED" -eq 1 ] && [ "$SWITCHOVER_PRIMARY_STOPPED" -eq 0 ]; then rollback_preconfigured_primary && warn "Staged settings rollback verified." || warn "Staged settings rollback could not be verified."; fi
    release_remote_lock; release_local_lock; cleanup_tmp
    if [ "$CHECK_ONLY" -eq 1 ]; then report_finalize; [ -n "$RESULT_FILE" ] && info "Check result file: $RESULT_FILE"; fi
    [ -n "$FINAL_EXIT_OVERRIDE" ] && rc=$FINAL_EXIT_OVERRIDE; exit "$rc"
}
trap on_exit EXIT
trap 'handle_signal SIGHUP 129' HUP
trap 'handle_signal SIGINT 130' INT
trap 'handle_signal SIGTERM 143' TERM

ask() { a_prompt=$1; a_default=${2:-}; if [ -n "$a_default" ]; then printf '%s [%s]: ' "$a_prompt" "$a_default" >&2; else printf '%s: ' "$a_prompt" >&2; fi; IFS= read -r a_value || return 1; [ -n "$a_value" ] || a_value=$a_default; printf '%s\n' "$a_value"; }
choose_yes_no() { cyn_prompt=$1; cyn_default=${2:-no}; while :; do cyn=$(ask "$cyn_prompt (yes/no)" "$cyn_default") || return 1; case "$cyn" in yes|YES|Yes|y|Y) return 0;; no|NO|No|n|N) return 1;; *) say "Enter yes or no.";; esac; done; }
confirm_word() { cw_word=$1; cw_message=$2; say "$cw_message"; printf 'Type "%s" to continue: ' "$cw_word" >&2; IFS= read -r cw_value || return 1; [ "$cw_value" = "$cw_word" ]; }
validate_timeout() { vt_value=$1; vt_name=$2; case "$vt_value" in ''|*[!0-9]*) error "$vt_name must be an integer."; return 1;; esac; [ "$vt_value" -ge "$TIMEOUT_MIN" ] 2>/dev/null || { error "$vt_name must be >= $TIMEOUT_MIN second."; return 1; }; [ "$vt_value" -le "$TIMEOUT_MAX" ] 2>/dev/null || { error "$vt_name must be <= $TIMEOUT_MAX seconds."; return 1; }; return 0; }

read_pid_line() { sed -n "${2}p" "$1" 2>/dev/null; }
canonicalize_pgdata() { (cd "$1" 2>/dev/null && pwd -P) || return 1; }
discover_pgdata_candidates() { { [ -n "${PGDATA:-}" ] && [ -f "$PGDATA/postmaster.pid" ] && printf '%s\n' "$PGDATA"; ps -eo args= 2>/dev/null | awk '/(^|\/)(postgres)([[:space:]]|$)/ {for(i=1;i<=NF;i++){if($i=="-D"&&(i+1)<=NF)print $(i+1);else if($i~/^--pgdata=/){sub(/^--pgdata=/,"",$i);print $i}}}'; } | sed '/^$/d' | sort -u; }
find_postgres_bindir_from_pid() { fp_pid=$1; if [ -n "$fp_pid" ] && [ -e "/proc/$fp_pid/exe" ] && command -v readlink >/dev/null 2>&1; then fp_exe=$(readlink "/proc/$fp_pid/exe" 2>/dev/null || true); [ -n "$fp_exe" ] && dirname "$fp_exe" && return 0; fi; return 1; }
find_binary() { fb_name=$1; fb_bindir=${2:-}; [ -n "$fb_bindir" ] && [ -x "$fb_bindir/$fb_name" ] && { printf '%s\n' "$fb_bindir/$fb_name"; return 0; }; [ -n "${PG_BINDIR:-}" ] && [ -x "$PG_BINDIR/$fb_name" ] && { printf '%s\n' "$PG_BINDIR/$fb_name"; return 0; }; fb_path=$(command -v "$fb_name" 2>/dev/null || true); [ -n "$fb_path" ] && [ -x "$fb_path" ] && { printf '%s\n' "$fb_path"; return 0; }; if command -v pg_config >/dev/null 2>&1; then fb_dir=$(pg_config --bindir 2>/dev/null || true); [ -n "$fb_dir" ] && [ -x "$fb_dir/$fb_name" ] && { printf '%s\n' "$fb_dir/$fb_name"; return 0; }; fi; return 1; }
binary_major_version() { "$1" --version 2>/dev/null | awk '{for(i=1;i<=NF;i++)if($i~/^[0-9]+([.][0-9]+)*$/){split($i,v,".");print v[1];exit}}'; }

psql_call() { pc_sql=$1; if [ -n "$PGUSER_LOCAL" ] && [ -n "$SOCKET_DIR" ]; then "$PSQL_BIN" -X -q -A -t -v ON_ERROR_STOP=1 -U "$PGUSER_LOCAL" -h "$SOCKET_DIR" -p "$PGPORT" -d "$DB_NAME" -c "$pc_sql"; elif [ -n "$PGUSER_LOCAL" ]; then "$PSQL_BIN" -X -q -A -t -v ON_ERROR_STOP=1 -U "$PGUSER_LOCAL" -p "$PGPORT" -d "$DB_NAME" -c "$pc_sql"; elif [ -n "$SOCKET_DIR" ]; then "$PSQL_BIN" -X -q -A -t -v ON_ERROR_STOP=1 -h "$SOCKET_DIR" -p "$PGPORT" -d "$DB_NAME" -c "$pc_sql"; else "$PSQL_BIN" -X -q -A -t -v ON_ERROR_STOP=1 -p "$PGPORT" -d "$DB_NAME" -c "$pc_sql"; fi; }
psql_call_var() { pv_name=$1; pv_value=$2; pv_sql=$3; if [ -n "$PGUSER_LOCAL" ] && [ -n "$SOCKET_DIR" ]; then "$PSQL_BIN" -X -q -A -t -v ON_ERROR_STOP=1 -v "$pv_name=$pv_value" -U "$PGUSER_LOCAL" -h "$SOCKET_DIR" -p "$PGPORT" -d "$DB_NAME" -c "$pv_sql"; elif [ -n "$PGUSER_LOCAL" ]; then "$PSQL_BIN" -X -q -A -t -v ON_ERROR_STOP=1 -v "$pv_name=$pv_value" -U "$PGUSER_LOCAL" -p "$PGPORT" -d "$DB_NAME" -c "$pv_sql"; elif [ -n "$SOCKET_DIR" ]; then "$PSQL_BIN" -X -q -A -t -v ON_ERROR_STOP=1 -v "$pv_name=$pv_value" -h "$SOCKET_DIR" -p "$PGPORT" -d "$DB_NAME" -c "$pv_sql"; else "$PSQL_BIN" -X -q -A -t -v ON_ERROR_STOP=1 -v "$pv_name=$pv_value" -p "$PGPORT" -d "$DB_NAME" -c "$pv_sql"; fi; }
psql_call_file() { pcf=$1; if [ -n "$PGUSER_LOCAL" ] && [ -n "$SOCKET_DIR" ]; then "$PSQL_BIN" -X -q -v ON_ERROR_STOP=1 -U "$PGUSER_LOCAL" -h "$SOCKET_DIR" -p "$PGPORT" -d "$DB_NAME" -f "$pcf"; elif [ -n "$PGUSER_LOCAL" ]; then "$PSQL_BIN" -X -q -v ON_ERROR_STOP=1 -U "$PGUSER_LOCAL" -p "$PGPORT" -d "$DB_NAME" -f "$pcf"; elif [ -n "$SOCKET_DIR" ]; then "$PSQL_BIN" -X -q -v ON_ERROR_STOP=1 -h "$SOCKET_DIR" -p "$PGPORT" -d "$DB_NAME" -f "$pcf"; else "$PSQL_BIN" -X -q -v ON_ERROR_STOP=1 -p "$PGPORT" -d "$DB_NAME" -f "$pcf"; fi; }
try_connect_local() { DB_NAME=$1; psql_call "SELECT 1" >/dev/null 2>&1; }

init_instance_from_pgdata() {
    ii_pgdata=$1; ii_quiet=${2:-0}; [ -d "$ii_pgdata" ] && [ -f "$ii_pgdata/postmaster.pid" ] || return 1
    PGDATA=$ii_pgdata; CANONICAL_PGDATA=$(canonicalize_pgdata "$PGDATA" 2>/dev/null || printf '%s' "$PGDATA")
    POSTMASTER_PID=$(read_pid_line "$PGDATA/postmaster.pid" 1); PGPORT=$(read_pid_line "$PGDATA/postmaster.pid" 4); SOCKET_DIR=$(read_pid_line "$PGDATA/postmaster.pid" 5); case "$SOCKET_DIR" in *,*) SOCKET_DIR=$(printf '%s' "$SOCKET_DIR" | awk -F, '{print $1}');; esac
    [ -n "$POSTMASTER_PID" ] && [ -n "$PGPORT" ] || return 1
    POSTMASTER_OPTIONS="$PG_START_OPTIONS"; if [ -z "$POSTMASTER_OPTIONS" ] && [ -r "$PGDATA/postmaster.opts" ]; then ii_line=$(sed -n '1p' "$PGDATA/postmaster.opts" 2>/dev/null || true); case "$ii_line" in *' '*) POSTMASTER_OPTIONS=${ii_line#* };; esac; fi
    ii_bindir=$(find_postgres_bindir_from_pid "$POSTMASTER_PID" 2>/dev/null || true); PSQL_BIN=$(find_binary psql "$ii_bindir" 2>/dev/null || true); PG_CTL_BIN=$(find_binary pg_ctl "$ii_bindir" 2>/dev/null || true); PG_CONTROLDATA_BIN=$(find_binary pg_controldata "$ii_bindir" 2>/dev/null || true); [ -n "$PSQL_BIN" ] || return 1
    if [ -z "$PGUSER_LOCAL" ]; then PGUSER_LOCAL=$(ps -o user= -p "$POSTMASTER_PID" 2>/dev/null | awk '{print $1;exit}'); [ -n "$PGUSER_LOCAL" ] || PGUSER_LOCAL=$(id -un 2>/dev/null || echo ""); fi
    if try_connect_local postgres; then :; elif try_connect_local template1; then :; else return 1; fi
    PG_VERSION_NUM=$(psql_call "SHOW server_version_num" 2>/dev/null | tr -d '[:space:]') || return 1; PG_MAJOR=$((PG_VERSION_NUM/10000)); SYSTEM_IDENTIFIER=$(psql_call "SELECT system_identifier FROM pg_control_system()" 2>/dev/null | tr -d '[:space:]') || return 1; LOCAL_ROLE=$(psql_call "SELECT CASE WHEN pg_is_in_recovery() THEN 'standby' ELSE 'primary' END" 2>/dev/null | tr -d '[:space:]') || return 1; CONFIG_FILE=$(psql_call "SHOW config_file" 2>/dev/null | sed -n '1p') || return 1; AUTO_CONF="$PGDATA/postgresql.auto.conf"
    [ "$PG_MAJOR" -ge 12 ] && [ "$PG_MAJOR" -le 18 ] || return 1
    for ii_bin in "$PG_CTL_BIN" "$PG_CONTROLDATA_BIN"; do [ -z "$ii_bin" ] && continue; ii_major=$(binary_major_version "$ii_bin" 2>/dev/null || true); [ -z "$ii_major" ] || [ "$ii_major" = "$PG_MAJOR" ] || return 1; done
    [ "$ii_quiet" -eq 0 ] && info "Connected: data_directory=$PGDATA port=$PGPORT role=$LOCAL_ROLE PostgreSQL=$PG_MAJOR"; return 0
}

select_local_instance() {
    sl_tmp=$(mktemp_safe) || fatal_validation "Could not create temporary file."; sl_inv=$(mktemp_safe) || fatal_validation "Could not create temporary file."; discover_pgdata_candidates > "$sl_tmp"; sl_n=0
    while IFS= read -r sl_pg; do [ -n "$sl_pg" ] || continue; sl_n=$((sl_n+1)); sl_port=$(read_pid_line "$sl_pg/postmaster.pid" 4); sl_ver=$(sed -n '1p' "$sl_pg/PG_VERSION" 2>/dev/null || echo unknown); printf '%s\t%s\t%s\t%s\n' "$sl_n" "$sl_pg" "${sl_port:-unknown}" "${sl_ver:-unknown}" >> "$sl_inv"; done < "$sl_tmp"
    [ "$sl_n" -gt 0 ] || { sl_manual=$(ask "PostgreSQL data_directory (PGDATA)" "") || fatal_usage "Input cancelled."; [ -n "$sl_manual" ] || fatal_usage "PGDATA is required."; init_instance_from_pgdata "$sl_manual" 0 || fatal_validation "Could not connect to PostgreSQL instance: $sl_manual"; return; }
    if [ "$sl_n" -eq 1 ]; then sl_pick=$(awk -F '\t' 'NR==1{print $2}' "$sl_inv"); init_instance_from_pgdata "$sl_pick" 0 || fatal_validation "Discovered PostgreSQL instance could not be initialized: $sl_pick"; return; fi
    section "PostgreSQL Instance Selection" "동일 서버의 여러 PostgreSQL 인스턴스 중 data_directory/Port를 기준으로 선택합니다."
    awk -F '\t' '{printf "  %s. data_directory=%s | port=%s | version=%s\n",$1,$2,$3,$4}' "$sl_inv"
    while :; do sl_sel=$(ask "Instance number or Port" "") || fatal_usage "Input cancelled."; case "$sl_sel" in ''|*[!0-9]*) say "Enter an instance number or Port."; continue;; esac; sl_pick=$(awk -F '\t' -v v="$sl_sel" '$1==v{print $2;exit}' "$sl_inv"); if [ -z "$sl_pick" ]; then sl_matches=$(awk -F '\t' -v v="$sl_sel" '$3==v{n++}END{print n+0}' "$sl_inv"); [ "$sl_matches" -le 1 ] || { say "Port matches more than one candidate. Select by instance number."; continue; }; sl_pick=$(awk -F '\t' -v v="$sl_sel" '$3==v{print $2;exit}' "$sl_inv"); fi; [ -n "$sl_pick" ] || { say "No matching instance."; continue; }; init_instance_from_pgdata "$sl_pick" 0 || fatal_validation "Could not initialize selected PostgreSQL instance."; return; done
}

derive_state_paths() { ds_base=${XDG_STATE_HOME:-}; if [ -z "$ds_base" ]; then if [ -n "${HOME:-}" ]; then ds_base="$HOME/.local/state"; else ds_base="$CANONICAL_PGDATA"; fi; fi; STATE_DIR="$ds_base/postgresql-role-switch"; if command -v cksum >/dev/null 2>&1; then STATE_KEY=$(printf '%s|%s' "$CANONICAL_PGDATA" "$SYSTEM_IDENTIFIER" | cksum | awk '{print $1}'); else STATE_KEY=$(printf '%s' "$SYSTEM_IDENTIFIER" | tr -cd '0-9A-Za-z'); fi; LOCAL_LOCK_DIR="${TMPDIR:-/tmp}/postgresql-role-switch-${STATE_KEY}.lock"; }
prepare_state_dir() { mkdir -p "$STATE_DIR" || fatal_validation "Cannot create state directory: $STATE_DIR"; chmod 700 "$STATE_DIR" 2>/dev/null || true; }
nearest_existing_parent() { nep=$1; while [ ! -e "$nep" ] && [ "$nep" != / ]; do nep=$(dirname "$nep"); done; printf '%s\n' "$nep"; }
check_config_writeability_no_change() {
    cc_failed=0
    if [ -e "$AUTO_CONF" ]; then [ -w "$AUTO_CONF" ] && record_result PASSED "postgresql.auto.conf write permission" "$AUTO_CONF is writable" || { record_result FAILED "postgresql.auto.conf write permission" "$AUTO_CONF is not writable"; cc_failed=1; }; else [ -w "$PGDATA" ] && record_result PASSED "postgresql.auto.conf create permission" "data_directory permits creation" || { record_result FAILED "postgresql.auto.conf create permission" "data_directory is not writable"; cc_failed=1; }; fi
    if [ -e "$PGDATA/standby.signal" ]; then [ -w "$PGDATA/standby.signal" ] && record_result PASSED "standby.signal write permission" "existing standby.signal is writable" || { record_result FAILED "standby.signal write permission" "existing standby.signal is not writable"; cc_failed=1; }; else [ -w "$PGDATA" ] && record_result PASSED "standby.signal create permission" "data_directory permits creation" || { record_result FAILED "standby.signal create permission" "data_directory is not writable"; cc_failed=1; }; fi
    if [ -d "$STATE_DIR" ]; then cc_parent=$STATE_DIR; else cc_parent=$(nearest_existing_parent "$STATE_DIR"); fi
    [ -d "$cc_parent" ] && [ -w "$cc_parent" ] && record_result PASSED "State directory permission" "existing parent is writable: $cc_parent" || { record_result FAILED "State directory permission" "cannot write state directory parent: $cc_parent"; cc_failed=1; }
    return "$cc_failed"
}
acquire_local_lock() { if mkdir "$LOCAL_LOCK_DIR" 2>/dev/null; then LOCAL_LOCK_HELD=1; printf '%s\n' "$$" > "$LOCAL_LOCK_DIR/pid"; printf '%s\n' "$CANONICAL_PGDATA" > "$LOCAL_LOCK_DIR/data_directory"; chmod 700 "$LOCAL_LOCK_DIR" 2>/dev/null || true; [ "$CHECK_ONLY" -eq 1 ] && record_result PASSED "Concurrent execution lock" "lock acquired for selected data_directory" >/dev/null; return 0; fi; al_pid=$(sed -n '1p' "$LOCAL_LOCK_DIR/pid" 2>/dev/null || echo unknown); [ "$CHECK_ONLY" -eq 1 ] && record_result FAILED "Concurrent execution lock" "another process or stale lock exists (pid=$al_pid)" >/dev/null; fatal_validation "Another process or stale lock already protects data_directory=$CANONICAL_PGDATA (pid=$al_pid, lock=$LOCAL_LOCK_DIR)."; }

current_topology_role() { ct_rec=$(psql_call "SELECT pg_is_in_recovery()" 2>/dev/null | tr -d '[:space:]') || return 1; ct_down=$(psql_call "SELECT count(*) FROM pg_stat_replication" 2>/dev/null | tr -d '[:space:]') || return 1; case "$ct_rec" in f|false) printf '%s\n' Primary;; *) if [ "$ct_down" -gt 0 ] 2>/dev/null; then printf '%s\n' "Cascading Standby"; else printf '%s\n' Standby; fi;; esac; }
pause_state() { if [ "$PG_MAJOR" -ge 14 ]; then psql_call "SELECT pg_get_wal_replay_pause_state()" 2>/dev/null | sed -n '1p'; else ps_p=$(psql_call "SELECT pg_is_wal_replay_paused()" 2>/dev/null | tr -d '[:space:]') || return 1; case "$ps_p" in t|true) printf '%s\n' "pause requested";; *) printf '%s\n' "not paused";; esac; fi; }
setting_exists() { psql_call_var n "$1" "SELECT CASE WHEN EXISTS(SELECT 1 FROM pg_settings WHERE name=:'n') THEN 1 ELSE 0 END" 2>/dev/null | grep '^1$' >/dev/null 2>&1; }
archive_mechanism_configured() { am_command=$(psql_call "SHOW archive_command" 2>/dev/null | sed -n '1p') || am_command=""; am_library=""; [ "$PG_MAJOR" -ge 15 ] && am_library=$(psql_call "SHOW archive_library" 2>/dev/null | sed -n '1p') || true; if [ -n "$am_command" ] || [ -n "$am_library" ]; then printf '%s\n' 1; else printf '%s\n' 0; fi; }
show_instance_summary() { section "PostgreSQL Instance" "선택한 인스턴스의 Streaming Replication 토폴로지를 표시합니다."; kv server_version_num "$PG_VERSION_NUM"; kv data_directory "$PGDATA"; kv port "$PGPORT"; kv "Current Role" "$(current_topology_role 2>/dev/null || echo unknown)"; kv system_identifier "$SYSTEM_IDENTIFIER"; kv config_file "$CONFIG_FILE"; }
topology_discovery() { section "Streaming Replication" "공식 통계 뷰를 사용해 Upstream/Downstream 관계를 확인합니다."; td_role=$(current_topology_role 2>/dev/null || echo unknown); kv "Current Role" "$td_role"; if [ "$LOCAL_ROLE" = standby ]; then td_wr=$(psql_call "SELECT COALESCE(status,'') || ' | sender_host=' || COALESCE(sender_host,'') || ' | sender_port=' || COALESCE(sender_port::text,'') FROM pg_stat_wal_receiver LIMIT 1" 2>/dev/null | sed -n '1p'); kv pg_stat_wal_receiver "${td_wr:-no rows}"; fi; td_ws=$(psql_call "SELECT count(*) FROM pg_stat_replication" 2>/dev/null | tr -d '[:space:]') || td_ws=unknown; kv "pg_stat_replication rows" "$td_ws"; }

disk_risk_check() {
    dr_df=$(df -Pk "$PGDATA" 2>/dev/null | awk 'NR==2{print $4"\t"$5}'); dr_free=$(printf '%s\n' "$dr_df" | awk -F '\t' '{print $1}'); dr_used=$(printf '%s\n' "$dr_df" | awk -F '\t' '{print $2}'); dr_wal=$(du -sk "$PGDATA/pg_wal" 2>/dev/null | awk '{print $1}'); [ -n "$dr_free" ] || { record_result FAILED "Disk free space" "df could not read filesystem for data_directory"; return 1; }; record_result PASSED "Filesystem free space" "available_kB=$dr_free used=$dr_used pg_wal_kB=${dr_wal:-unknown}"
    if [ "$LOCAL_ROLE" = standby ]; then dr_pause=$(pause_state 2>/dev/null || echo unknown); dr_backlog=$(psql_call "SELECT COALESCE(pg_wal_lsn_diff(pg_last_wal_receive_lsn(),pg_last_wal_replay_lsn())::bigint,0)" 2>/dev/null | tr -d '[:space:]') || dr_backlog=unknown; if [ "$dr_pause" != "not paused" ] && [ "$dr_pause" != false ] && [ "$dr_pause" != f ]; then record_result WARNING "WAL Replay disk risk" "replay_state=$dr_pause receive_to_replay_backlog_bytes=$dr_backlog; WAL reception can continue while replay is paused"; else record_result PASSED "WAL Replay disk risk" "replay not paused; receive_to_replay_backlog_bytes=$dr_backlog"; fi; dr_receiver=$(psql_call "SELECT count(*) FROM pg_stat_wal_receiver" 2>/dev/null | tr -d '[:space:]') || dr_receiver=0; dr_pc=$(psql_call "SELECT setting FROM pg_settings WHERE name='primary_conninfo'" 2>/dev/null | sed -n '1p') || dr_pc=""; if [ -n "$dr_pc" ] && [ "$dr_receiver" -eq 0 ] 2>/dev/null; then record_result WARNING "WAL Receiver connection risk" "primary_conninfo is configured but pg_stat_wal_receiver has no row; upstream/archive retention must be checked"; fi
    else dr_slots=$(psql_call "SELECT count(*) FROM pg_replication_slots" 2>/dev/null | tr -d '[:space:]') || dr_slots=0; dr_inactive=$(psql_call "SELECT count(*) FROM pg_replication_slots WHERE NOT active" 2>/dev/null | tr -d '[:space:]') || dr_inactive=0; dr_retained=$(psql_call "SELECT COALESCE(sum(pg_wal_lsn_diff(pg_current_wal_lsn(),restart_lsn))::bigint,0) FROM pg_replication_slots WHERE restart_lsn IS NOT NULL" 2>/dev/null | tr -d '[:space:]') || dr_retained=unknown; if setting_exists max_slot_wal_keep_size; then dr_limit=$(psql_call "SHOW max_slot_wal_keep_size" 2>/dev/null | sed -n '1p'); else dr_limit="not available on PostgreSQL $PG_MAJOR"; fi; if [ "$dr_slots" -gt 0 ] 2>/dev/null; then if [ "$dr_inactive" -gt 0 ] 2>/dev/null; then record_result WARNING "Replication slot WAL retention" "slots=$dr_slots inactive=$dr_inactive retained_bytes=$dr_retained max_slot_wal_keep_size=$dr_limit"; else record_result PASSED "Replication slot WAL retention" "slots=$dr_slots inactive=0 retained_bytes=$dr_retained max_slot_wal_keep_size=$dr_limit"; fi; else record_result PASSED "Replication slot WAL retention" "no replication slots"; fi; fi; return 0
}

ssh_probe() { [ "$REMOTE_TRANSPORT" = ssh ] || return 0; ssh -T -o BatchMode=yes -o ConnectTimeout="$SSH_CONNECT_TIMEOUT" "$REMOTE_TARGET" 'sh -c "exit 0"' >/dev/null 2>&1; }
remote_build_command() { rb="sh -s --"; for ra in "$@"; do rb="$rb $(shell_quote "$ra")"; done; printf '%s\n' "$rb"; }
invoke_on_transport() { io_transport=$1; io_target=$2; shift 2; if [ "$io_transport" = local ]; then sh "$SCRIPT_PATH" "$@"; return $?; fi; command -v ssh >/dev/null 2>&1 || return 127; io_cmd=$(remote_build_command "$@"); ssh -T -o BatchMode=yes -o ConnectTimeout="$SSH_CONNECT_TIMEOUT" "$io_target" "$io_cmd" < "$SCRIPT_PATH"; }
remote_invoke() { invoke_on_transport "$REMOTE_TRANSPORT" "$REMOTE_TARGET" "$@"; }
remote_invoke_file_or_die() { rif_out=$1; shift; remote_invoke "$@" > "$rif_out" 2>/dev/null; rif_rc=$?; [ "$rif_rc" -eq 0 ] && return 0; if [ "$REMOTE_TRANSPORT" = ssh ]; then [ "$rif_rc" -eq 255 ] && fatal_remote "SSH connection to $REMOTE_TARGET failed during remote validation."; ssh_probe || fatal_remote "SSH connection to $REMOTE_TARGET failed during remote validation."; fi; fatal_validation "Remote PostgreSQL validation failed (rc=$rif_rc)."; }

choose_remote_transport() { crt_default=$CANDIDATE_CLIENT; [ "$crt_default" = local ] || [ -n "$crt_default" ] || crt_default=""; section "Remote Execution Transport" "Standby 인스턴스 검증에 사용할 전송 방식을 선택합니다."; say "  SSH"; say "     비대화형 SSH로 Standby 서버에서 동일 스크립트의 내부 검증 기능을 실행합니다."; say "  local"; say "     동일 OS 서버의 다른 PostgreSQL 인스턴스인 경우 사용합니다."; crt_host=$(ask "SSH host or 'local'" "$crt_default") || fatal_usage "Input cancelled."; if [ "$crt_host" = local ]; then REMOTE_TRANSPORT=local; REMOTE_TARGET=local; REMOTE_SSH_HOST=local; REMOTE_SSH_USER=$(id -un 2>/dev/null || echo ""); return; fi; [ -n "$crt_host" ] || fatal_usage "SSH host is required."; command -v ssh >/dev/null 2>&1 || fatal_remote "ssh client is not available; nothing is installed automatically."; REMOTE_TRANSPORT=ssh; REMOTE_SSH_HOST=$crt_host; REMOTE_SSH_USER=$(ask "SSH user" "$(id -un 2>/dev/null || echo '')") || fatal_usage "Input cancelled."; [ -n "$REMOTE_SSH_USER" ] || fatal_usage "SSH user is required."; REMOTE_TARGET="$REMOTE_SSH_USER@$REMOTE_SSH_HOST"; ssh_probe || fatal_remote "Non-interactive SSH connection failed for $REMOTE_TARGET."; [ "$CHECK_ONLY" -eq 1 ] && record_result PASSED "Non-interactive SSH" "BatchMode connection succeeded to $REMOTE_TARGET" >/dev/null; }

primary_standby_list_file() { psl=$1; psql_call "SELECT pid::text||E'\\t'||application_name||E'\\t'||COALESCE(client_addr::text,'local')||E'\\t'||usename||E'\\t'||state||E'\\t'||sync_state||E'\\t'||COALESCE(replay_lsn::text,'')||E'\\t'||COALESCE(pg_wal_lsn_diff(pg_current_wal_lsn(),replay_lsn)::bigint::text,'')||E'\\t'||COALESCE((SELECT slot_name FROM pg_replication_slots s WHERE s.active_pid=r.pid LIMIT 1),'') FROM pg_stat_replication r ORDER BY application_name,client_addr NULLS FIRST,pid" > "$psl"; }
select_primary_candidate() { spc=$1; primary_standby_list_file "$spc" || fatal_validation "Could not query pg_stat_replication."; DIRECT_STANDBY_COUNT=$(wc -l < "$spc" | tr -d '[:space:]'); [ "$DIRECT_STANDBY_COUNT" -gt 0 ] || fatal_validation "No directly connected Standby exists in pg_stat_replication."; section "Standby Server Selection" "현재 Primary의 pg_stat_replication에 직접 연결된 Standby 중 새 Primary 후보를 선택합니다."; awk -F '\t' '{printf "  %d. application_name=%s | client_addr=%s | state=%s | sync_state=%s | replay_lsn=%s | lag_bytes=%s | slot=%s | pid=%s\n",NR,$2,$3,$5,$6,$7,$8,$9,$1}' "$spc"; while :; do spn=$(ask "Standby Server number" "") || fatal_usage "Input cancelled."; case "$spn" in ''|*[!0-9]*) say "Enter a number."; continue;; esac; spl=$(sed -n "${spn}p" "$spc"); [ -n "$spl" ] || { say "Invalid selection."; continue; }; CANDIDATE_PID=$(printf '%s\n' "$spl"|awk -F '\t' '{print $1}'); CANDIDATE_APP=$(printf '%s\n' "$spl"|awk -F '\t' '{print $2}'); CANDIDATE_CLIENT=$(printf '%s\n' "$spl"|awk -F '\t' '{print $3}'); CANDIDATE_REPL_USER=$(printf '%s\n' "$spl"|awk -F '\t' '{print $4}'); CANDIDATE_STATE=$(printf '%s\n' "$spl"|awk -F '\t' '{print $5}'); CANDIDATE_SYNC_STATE=$(printf '%s\n' "$spl"|awk -F '\t' '{print $6}'); CANDIDATE_REPLAY_LSN=$(printf '%s\n' "$spl"|awk -F '\t' '{print $7}'); CANDIDATE_REPLAY_BYTES=$(printf '%s\n' "$spl"|awk -F '\t' '{print $8}'); CANDIDATE_SLOT=$(printf '%s\n' "$spl"|awk -F '\t' '{print $9}'); return; done; }

remote_select_instance() { rsi=$(mktemp_safe) || fatal_validation "Could not create remote discovery file."; remote_invoke_file_or_die "$rsi" --remote-list "$SYSTEM_IDENTIFIER"; rsc=$(awk -F '\t' '$1=="INSTANCE"{c++}END{print c+0}' "$rsi"); [ "$rsc" -gt 0 ] || fatal_validation "No matching running Standby with system_identifier=$SYSTEM_IDENTIFIER was found."; section "Standby Server Instance Selection" "동일 system_identifier를 가진 실행 중 Standby 인스턴스를 선택합니다."; awk -F '\t' '$1=="INSTANCE"{i++;printf "  %d. data_directory=%s | port=%s | version=%s | role=%s | topology=%s | receiver=%s | sender=%s:%s | downstream=%s\n",i,$2,$3,$4,$5,$17,$12,$7,$8,$18}' "$rsi"; if [ "$rsc" -eq 1 ]; then rsp=1; else rsp=$(ask "Remote instance number" "") || fatal_usage "Input cancelled."; fi; case "$rsp" in ''|*[!0-9]*) fatal_usage "Invalid remote instance selection.";; esac; rsl=$(awk -F '\t' -v n="$rsp" '$1=="INSTANCE"{i++;if(i==n)print}' "$rsi"); [ -n "$rsl" ] || fatal_usage "Invalid remote instance selection."; REMOTE_PGDATA=$(printf '%s\n' "$rsl"|awk -F '\t' '{print $2}'); REMOTE_PORT=$(printf '%s\n' "$rsl"|awk -F '\t' '{print $3}'); REMOTE_VERSION_NUM=$(printf '%s\n' "$rsl"|awk -F '\t' '{print $4}'); REMOTE_MAJOR=$((REMOTE_VERSION_NUM/10000)); REMOTE_ROLE=$(printf '%s\n' "$rsl"|awk -F '\t' '{print $5}'); REMOTE_SYSTEM_IDENTIFIER=$(printf '%s\n' "$rsl"|awk -F '\t' '{print $6}'); REMOTE_SENDER_HOST=$(printf '%s\n' "$rsl"|awk -F '\t' '{print $7}'); REMOTE_SENDER_PORT=$(printf '%s\n' "$rsl"|awk -F '\t' '{print $8}'); REMOTE_REPLAY_LSN=$(printf '%s\n' "$rsl"|awk -F '\t' '{print $9}'); REMOTE_PAUSE_STATE=$(printf '%s\n' "$rsl"|awk -F '\t' '{print $10}'); REMOTE_DELAY_MS=$(printf '%s\n' "$rsl"|awk -F '\t' '{print $11}'); REMOTE_RECEIVER_STATUS=$(printf '%s\n' "$rsl"|awk -F '\t' '{print $12}'); REMOTE_SYNC_STANDBY_NAMES=$(printf '%s\n' "$rsl"|awk -F '\t' '{print $13}'); REMOTE_DEFAULT_TX_READ_ONLY=$(printf '%s\n' "$rsl"|awk -F '\t' '{print $14}'); REMOTE_ARCHIVE_MODE=$(printf '%s\n' "$rsl"|awk -F '\t' '{print $15}'); REMOTE_ARCHIVE_READY=$(printf '%s\n' "$rsl"|awk -F '\t' '{print $16}'); REMOTE_TOPOLOGY_ROLE=$(printf '%s\n' "$rsl"|awk -F '\t' '{print $17}'); REMOTE_DOWNSTREAM_COUNT=$(printf '%s\n' "$rsl"|awk -F '\t' '{print $18}'); REMOTE_RECOVERY_TARGET_TIMELINE=$(printf '%s\n' "$rsl"|awk -F '\t' '{print $19}'); REMOTE_RECEIVER_SLOT=$(printf '%s\n' "$rsl"|awk -F '\t' '{print $20}'); }

remote_environment_check() { rec=$(mktemp_safe) || fatal_validation "Could not create remote environment file."; remote_invoke_file_or_die "$rec" --remote-env-check "$REMOTE_PGDATA"; re_user=$(awk -F '\t' '$1=="ENV"{print $2}' "$rec"); re_owner=$(awk -F '\t' '$1=="ENV"{print $3}' "$rec"); re_pgctl=$(awk -F '\t' '$1=="ENV"{print $5}' "$rec"); re_exec=$(awk -F '\t' '$1=="ENV"{print $6}' "$rec"); re_path=$(awk -F '\t' '$1=="ENV"{print $4}' "$rec"); if [ -n "$re_user" ] && [ "$re_user" = "$re_owner" ]; then record_result PASSED "Remote PostgreSQL OS user" "ssh_user=$re_user postmaster_owner=$re_owner"; else record_result FAILED "Remote PostgreSQL OS user" "ssh_user=${re_user:-unknown} postmaster_owner=${re_owner:-unknown}"; fi; [ "$re_exec" = 1 ] && record_result PASSED "Remote pg_ctl permission" "pg_ctl=$re_pgctl executable" || record_result FAILED "Remote pg_ctl permission" "pg_ctl=${re_pgctl:-not found} not executable"; [ -n "$re_path" ] && record_result PASSED "Remote non-interactive PATH" "$re_path" || record_result FAILED "Remote non-interactive PATH" "PATH is empty"; }
remote_config_write_check() { rcc=$(mktemp_safe) || fatal_validation "Could not create remote permission file."; remote_invoke_file_or_die "$rcc" --remote-config-write-check "$REMOTE_PGDATA"; while IFS="$TAB" read -r r_status r_item r_detail; do [ "$r_status" = CHECK ] || continue; case "$r_detail" in PASS:*) record_result PASSED "Remote $r_item" "${r_detail#PASS:}";; FAIL:*) record_result FAILED "Remote $r_item" "${r_detail#FAIL:}";; esac; done < "$rcc"; }
acquire_remote_lock() { REMOTE_LOCK_TOKEN="$$.$(date +%s 2>/dev/null || echo 0)"; ar=$(mktemp_safe) || fatal_validation "Could not create remote lock response file."; if remote_invoke --remote-lock-acquire "$REMOTE_PGDATA" "$REMOTE_LOCK_TOKEN" > "$ar" 2>/dev/null; then REMOTE_LOCK_HELD=1; record_result PASSED "Remote concurrent execution lock" "lock acquired for candidate data_directory"; return 0; fi; if [ "$REMOTE_TRANSPORT" = ssh ] && ! ssh_probe; then fatal_remote "SSH connection failed while acquiring candidate lock."; fi; record_result FAILED "Remote concurrent execution lock" "another process or stale lock exists for candidate data_directory"; fatal_validation "Candidate data_directory is already protected by another process or stale lock."; }

primary_conninfo_target_crosscheck() { section "primary_conninfo Target Cross-check" "sender_host 문자열 비교 대신 Standby에서 sender_host:sender_port로 실제 SQL 연결하여 system_identifier와 port를 확인합니다."; pct_user=$(ask "Database probe user on current Primary" "$PGUSER_LOCAL") || fatal_usage "Input cancelled."; [ -n "$pct_user" ] || fatal_usage "Database probe user is required."; pct=$(mktemp_safe) || fatal_validation "Could not create upstream probe file."; if remote_invoke --remote-probe-upstream "$REMOTE_PGDATA" "$pct_user" > "$pct" 2>/dev/null; then :; else if [ "$REMOTE_TRANSPORT" = ssh ] && ! ssh_probe; then fatal_remote "SSH connection failed during primary_conninfo target cross-check."; fi; record_result FAILED "primary_conninfo target cross-check" "actual SQL connection to pg_stat_wal_receiver sender_host:sender_port failed; prepare .pgpass/certificate/pg_hba.conf for probe user"; return 1; fi; p_sys=$(awk -F '\t' '$1=="UPSTREAM"{print $2}' "$pct"); p_port=$(awk -F '\t' '$1=="UPSTREAM"{print $3}' "$pct"); p_role=$(awk -F '\t' '$1=="UPSTREAM"{print $4}' "$pct"); if [ "$p_sys" = "$SYSTEM_IDENTIFIER" ] && [ "$p_port" = "$PGPORT" ] && [ "$p_role" = primary ]; then record_result PASSED "primary_conninfo target cross-check" "actual upstream connection verified system_identifier=$p_sys port=$p_port role=$p_role"; return 0; fi; record_result FAILED "primary_conninfo target cross-check" "actual upstream identity mismatch system_identifier=${p_sys:-unknown} port=${p_port:-unknown} role=${p_role:-unknown}"; return 1; }

candidate_downstream_check() { [ "$REMOTE_DOWNSTREAM_COUNT" -gt 0 ] 2>/dev/null || { record_result PASSED "Cascading Replication" "candidate has no downstream Standby"; return 0; }; cd=$(mktemp_safe) || fatal_validation "Could not create downstream file."; remote_invoke_file_or_die "$cd" --remote-downstreams "$REMOTE_PGDATA"; cd_count=$(awk -F '\t' '$1=="DOWNSTREAM"{c++}END{print c+0}' "$cd"); [ "$cd_count" = "$REMOTE_DOWNSTREAM_COUNT" ] || { record_result FAILED "Cascading Replication" "candidate downstream count changed during precheck"; return 1; }; cd_bad=$(awk -F '\t' '$1=="DOWNSTREAM" && $4!="streaming"{c++}END{print c+0}' "$cd"); if [ "$cd_bad" -gt 0 ]; then record_result FAILED "Cascading Replication" "$cd_bad downstream WAL sender connection(s) are not state=streaming"; return 1; fi; record_result PASSED "Cascading Replication" "$REMOTE_DOWNSTREAM_COUNT downstream connection(s) are state=streaming"; cd_i=1; while [ "$cd_i" -le "$cd_count" ]; do cd_line=$(awk -F '\t' -v n="$cd_i" '$1=="DOWNSTREAM"{i++;if(i==n)print}' "$cd"); cd_app=$(printf '%s\n' "$cd_line"|awk -F '\t' '{print $2}'); cd_client=$(printf '%s\n' "$cd_line"|awk -F '\t' '{print $3}'); cd_slot=$(printf '%s\n' "$cd_line"|awk -F '\t' '{print $7}'); section "Downstream Standby Verification" "Cascading Standby의 Downstream 인스턴스가 새 timeline을 계속 따라갈 수 있는지 확인합니다."; kv application_name "$cd_app"; kv client_addr "$cd_client"; cd_host=$(ask "Downstream SSH host or 'local'" "$cd_client") || fatal_usage "Input cancelled."; [ -n "$cd_host" ] || fatal_usage "Downstream host is required."; if [ "$cd_host" = local ]; then cd_transport=local; cd_target=local; else command -v ssh >/dev/null 2>&1 || fatal_remote "ssh client is not available for downstream verification."; cd_user=$(ask "Downstream SSH user" "$(id -un 2>/dev/null || echo '')") || fatal_usage "Input cancelled."; [ -n "$cd_user" ] || fatal_usage "Downstream SSH user is required."; cd_transport=ssh; cd_target="$cd_user@$cd_host"; ssh -T -o BatchMode=yes -o ConnectTimeout="$SSH_CONNECT_TIMEOUT" "$cd_target" 'sh -c "exit 0"' >/dev/null 2>&1 || fatal_remote "Non-interactive SSH failed for downstream $cd_target."; fi; cd_inst=$(mktemp_safe) || fatal_validation "Could not create downstream instance file."; invoke_on_transport "$cd_transport" "$cd_target" --remote-list-downstream "$SYSTEM_IDENTIFIER" "$REMOTE_PORT" "$cd_slot" > "$cd_inst" 2>/dev/null; cd_rc=$?; if [ "$cd_rc" -ne 0 ]; then [ "$cd_transport" = ssh ] && [ "$cd_rc" -eq 255 ] && fatal_remote "SSH failed while discovering downstream $cd_target."; record_result FAILED "Downstream Standby" "could not discover matching instance for application_name=$cd_app"; cd_i=$((cd_i+1)); continue; fi; cd_matches=$(awk -F '\t' '$1=="DOWNSTREAM_INSTANCE"{c++}END{print c+0}' "$cd_inst"); if [ "$cd_matches" -eq 0 ]; then record_result FAILED "Downstream Standby" "no matching streaming Standby for application_name=$cd_app"; cd_i=$((cd_i+1)); continue; fi; if [ "$cd_matches" -eq 1 ]; then cd_pick=1; else awk -F '\t' '$1=="DOWNSTREAM_INSTANCE"{i++;printf "  %d. data_directory=%s | port=%s | sender=%s:%s | status=%s | recovery_target_timeline=%s | slot=%s\\n",i,$2,$3,$6,$7,$8,$9,$10}' "$cd_inst"; cd_pick=$(ask "Downstream instance number" "") || fatal_usage "Input cancelled."; fi; case "$cd_pick" in ''|*[!0-9]*) fatal_usage "Invalid downstream instance selection.";; esac; cd_sel=$(awk -F '\t' -v n="$cd_pick" '$1=="DOWNSTREAM_INSTANCE"{i++;if(i==n)print}' "$cd_inst"); [ -n "$cd_sel" ] || fatal_usage "Invalid downstream instance selection."; cd_tl=$(printf '%s\n' "$cd_sel"|awk -F '\t' '{print $9}'); if [ "$cd_tl" = latest ]; then record_result PASSED "Downstream recovery_target_timeline" "$cd_app: latest"; else record_result FAILED "Downstream recovery_target_timeline" "$cd_app: ${cd_tl:-unknown}"; fi; cd_i=$((cd_i+1)); done; }

unselected_standby_check() { [ "$DIRECT_STANDBY_COUNT" -gt 1 ] 2>/dev/null || { UNSELECTED_STANDBY_COUNT=0; record_result PASSED "Unselected Standby topology" "no additional direct Standby"; return 0; }; usf=$(mktemp_safe) || fatal_validation "Could not create direct Standby refresh file."; primary_standby_list_file "$usf" || fatal_validation "Could not refresh pg_stat_replication."; UNSELECTED_STANDBY_COUNT=$(awk -F '\t' -v p="$CANDIDATE_PID" '$1!=p{c++}END{print c+0}' "$usf"); us_i=1; while [ "$us_i" -le "$UNSELECTED_STANDBY_COUNT" ]; do us_line=$(awk -F '\t' -v p="$CANDIDATE_PID" -v n="$us_i" '$1!=p{i++;if(i==n)print}' "$usf"); us_app=$(printf '%s\n' "$us_line"|awk -F '\t' '{print $2}'); us_client=$(printf '%s\n' "$us_line"|awk -F '\t' '{print $3}'); us_state=$(printf '%s\n' "$us_line"|awk -F '\t' '{print $5}'); us_slot=$(printf '%s\n' "$us_line"|awk -F '\t' '{print $9}'); [ "$us_state" = streaming ] || { record_result FAILED "Unselected Standby $us_app" "pg_stat_replication.state=$us_state"; us_i=$((us_i+1)); continue; }; section "Unselected Standby Verification" "역할 전환 후 former Primary를 계속 Upstream으로 사용할 Standby의 timeline 설정을 확인합니다."; us_host=$(ask "Standby SSH host or 'local' for $us_app" "$us_client") || fatal_usage "Input cancelled."; [ -n "$us_host" ] || fatal_usage "Standby host is required."; if [ "$us_host" = local ]; then us_transport=local; us_target=local; else command -v ssh >/dev/null 2>&1 || fatal_remote "ssh client is not available for unselected Standby verification."; us_user=$(ask "Standby SSH user for $us_app" "$(id -un 2>/dev/null || echo '')") || fatal_usage "Input cancelled."; [ -n "$us_user" ] || fatal_usage "Standby SSH user is required."; us_transport=ssh; us_target="$us_user@$us_host"; ssh -T -o BatchMode=yes -o ConnectTimeout="$SSH_CONNECT_TIMEOUT" "$us_target" 'sh -c "exit 0"' >/dev/null 2>&1 || fatal_remote "Non-interactive SSH failed for $us_target."; fi; us_inst=$(mktemp_safe) || fatal_validation "Could not create unselected Standby instance file."; invoke_on_transport "$us_transport" "$us_target" --remote-list-downstream "$SYSTEM_IDENTIFIER" "$PGPORT" "$us_slot" > "$us_inst" 2>/dev/null; us_rc=$?; if [ "$us_rc" -ne 0 ]; then [ "$us_transport" = ssh ] && [ "$us_rc" -eq 255 ] && fatal_remote "SSH failed while discovering $us_app."; record_result FAILED "Unselected Standby $us_app" "matching instance discovery failed"; us_i=$((us_i+1)); continue; fi; us_matches=$(awk -F '\t' '$1=="DOWNSTREAM_INSTANCE"{c++}END{print c+0}' "$us_inst"); if [ "$us_matches" -eq 0 ]; then record_result FAILED "Unselected Standby $us_app" "no matching streaming receiver found"; us_i=$((us_i+1)); continue; fi; if [ "$us_matches" -eq 1 ]; then us_pick=1; else awk -F '\t' '$1=="DOWNSTREAM_INSTANCE"{i++;printf "  %d. data_directory=%s | port=%s | sender=%s:%s | status=%s | recovery_target_timeline=%s | slot=%s\\n",i,$2,$3,$6,$7,$8,$9,$10}' "$us_inst"; us_pick=$(ask "Standby instance number for $us_app" "") || fatal_usage "Input cancelled."; fi; case "$us_pick" in ''|*[!0-9]*) fatal_usage "Invalid Standby instance selection.";; esac; us_sel=$(awk -F '\t' -v n="$us_pick" '$1=="DOWNSTREAM_INSTANCE"{i++;if(i==n)print}' "$us_inst"); us_tl=$(printf '%s\n' "$us_sel"|awk -F '\t' '{print $9}'); [ "$us_tl" = latest ] && record_result PASSED "Unselected Standby $us_app" "streaming and recovery_target_timeline=latest" || record_result FAILED "Unselected Standby $us_app" "recovery_target_timeline=${us_tl:-unknown}"; us_i=$((us_i+1)); done; }

logical_replication_slot_precheck() { lrs_count=$(psql_call "SELECT count(*) FROM pg_replication_slots WHERE slot_type='logical'" 2>/dev/null|tr -d '[:space:]') || { record_result FAILED "Logical replication slots" "could not query pg_replication_slots"; return 1; }; [ "$lrs_count" -gt 0 ] 2>/dev/null || { record_result PASSED "Logical replication slots" "none"; return 0; }; if [ "$PG_MAJOR" -lt 17 ]; then if [ "$CHECK_ONLY" -eq 1 ]; then record_result "MANUAL CHECK" "Logical replication slots" "PostgreSQL $PG_MAJOR has $lrs_count logical slot(s); continuity is not automatically transferred by physical promotion"; else warn "PostgreSQL $PG_MAJOR has $lrs_count logical replication slot(s); handle logical consumers/slots separately."; confirm_word CONTINUE "Logical replication continuity has a separate approved plan." || fatal_validation "Logical replication slot continuity not confirmed."; fi; return 0; fi; lrs_non=$(psql_call "SELECT count(*) FROM pg_replication_slots WHERE slot_type='logical' AND (NOT failover OR temporary)" 2>/dev/null|tr -d '[:space:]') || lrs_non=0; if [ "$lrs_non" -gt 0 ] 2>/dev/null; then if [ "$CHECK_ONLY" -eq 1 ]; then record_result "MANUAL CHECK" "Logical failover slots" "$lrs_non logical slot(s) are not persistent failover-enabled slots"; else confirm_word CONTINUE "$lrs_non logical slot(s) are not persistent failover-enabled slots. Continue only with a separate plan." || fatal_validation "Non-failover logical slots not approved."; fi; fi; lrs_tmp=$(mktemp_safe) || fatal_validation "Could not create logical slot list."; psql_call "SELECT slot_name FROM pg_replication_slots WHERE slot_type='logical' AND failover AND NOT temporary ORDER BY slot_name" > "$lrs_tmp" || { record_result FAILED "Logical failover slots" "could not list failover slots"; return 1; }; while IFS= read -r lrs_slot; do [ -n "$lrs_slot" ] || continue; if remote_invoke --remote-check-logical-slot "$REMOTE_PGDATA" "$lrs_slot" >/dev/null 2>&1; then record_result PASSED "Logical failover slot $lrs_slot" "synced and valid on candidate"; else [ "$REMOTE_TRANSPORT" = ssh ] && ! ssh_probe && fatal_remote "SSH failed while checking logical failover slot $lrs_slot."; record_result FAILED "Logical failover slot $lrs_slot" "not synced/valid on candidate"; fi; done < "$lrs_tmp"; }

precheck_external_ha() { peh=$(ps -eo comm=,args= 2>/dev/null | awk '{l=tolower($0)} l~/patroni|repmgrd|pg_autoctl|pacemakerd|corosync/{print}' | sed '/pg-role-switch/d' | sed -n '1,5p'); if [ -n "$peh" ]; then if [ "$CHECK_ONLY" -eq 1 ]; then record_result "MANUAL CHECK" "External HA manager" "possible HA manager detected; maintenance/pause state must be verified"; else warn "Possible external HA manager detected:"; printf '%s\n' "$peh" | sed 's/^/  /' >&2; choose_yes_no "External HA manager is in documented maintenance/pause mode" no || fatal_validation "External HA manager maintenance state not confirmed."; fi; else record_result PASSED "External HA manager" "no known external HA-manager process detected locally"; fi; }
startup_options_guard() { sog=$(psql_call "SELECT count(*) FROM pg_settings WHERE source='command line' AND name<>'data_directory'" 2>/dev/null|tr -d '[:space:]')||sog=0; if [ -z "$POSTMASTER_OPTIONS" ] && [ "$sog" -gt 0 ] 2>/dev/null; then record_result FAILED "PostgreSQL startup options" "command-line settings exist but postmaster.opts/start options were not preserved"; return 1; fi; if [ -z "$POSTMASTER_OPTIONS" ] && [ "$CONFIG_FILE" != "$PGDATA/postgresql.conf" ]; then record_result FAILED "PostgreSQL startup options" "config_file is outside data_directory and reusable startup options were not discovered"; return 1; fi; record_result PASSED "PostgreSQL startup options" "restart options can be preserved"; return 0; }
revalidate_candidate_identity() { rci=$(psql_call_var p "$CANDIDATE_PID" "SELECT application_name||E'\\t'||COALESCE(client_addr::text,'local')||E'\\t'||usename||E'\\t'||state||E'\\t'||COALESCE((SELECT slot_name FROM pg_replication_slots s WHERE s.active_pid=r.pid LIMIT 1),'') FROM pg_stat_replication r WHERE pid=:'p'::integer" 2>/dev/null | sed -n '1p') || rci=""; rce=$(printf '%s\t%s\t%s\tstreaming\t%s' "$CANDIDATE_APP" "$CANDIDATE_CLIENT" "$CANDIDATE_REPL_USER" "${CANDIDATE_SLOT:-}"); [ "$rci" = "$rce" ] || { record_result FAILED "Candidate identity revalidation" "selected pg_stat_replication row changed or left state=streaming"; return 1; }; if remote_invoke --remote-validate-candidate "$REMOTE_PGDATA" "$SYSTEM_IDENTIFIER" "$PGPORT" "${CANDIDATE_SLOT:-}" "$REMOTE_DOWNSTREAM_COUNT" >/dev/null 2>&1; then record_result PASSED "Candidate identity revalidation" "local WAL sender row and remote WAL receiver/topology remain consistent"; return 0; fi; [ "$REMOTE_TRANSPORT" = ssh ] && ! ssh_probe && fatal_remote "SSH failed during candidate revalidation."; record_result FAILED "Candidate identity revalidation" "remote role/system_identifier/WAL Receiver/timeline/downstream state changed"; return 1; }

planned_switchover_precheck() {
    [ "$LOCAL_ROLE" = primary ] || { record_result FAILED "Current Role" "Planned Switchover must be started on current Primary"; return 1; }; record_result PASSED "Current Role" Primary; check_config_writeability_no_change || true; disk_risk_check || true; precheck_external_ha
    psf=$(mktemp_safe) || fatal_validation "Could not create candidate file."; select_primary_candidate "$psf"; [ "$CANDIDATE_STATE" = streaming ] && record_result PASSED "Candidate pg_stat_replication.state" streaming || record_result FAILED "Candidate pg_stat_replication.state" "${CANDIDATE_STATE:-missing}"; [ -n "$CANDIDATE_REPLAY_LSN" ] && record_result PASSED "Candidate replay_lsn" "$CANDIDATE_REPLAY_LSN" || record_result FAILED "Candidate replay_lsn" empty
    choose_remote_transport; remote_select_instance; acquire_remote_lock; remote_environment_check; remote_config_write_check
    [ "$REMOTE_ROLE" = standby ] && record_result PASSED "Candidate Current Role" "$REMOTE_TOPOLOGY_ROLE" || record_result FAILED "Candidate Current Role" "$REMOTE_ROLE"; [ "$REMOTE_SYSTEM_IDENTIFIER" = "$SYSTEM_IDENTIFIER" ] && record_result PASSED system_identifier "$SYSTEM_IDENTIFIER matches" || record_result FAILED system_identifier "primary=$SYSTEM_IDENTIFIER candidate=$REMOTE_SYSTEM_IDENTIFIER"; [ "$REMOTE_MAJOR" -eq "$PG_MAJOR" ] 2>/dev/null && record_result PASSED "PostgreSQL major version" "$PG_MAJOR matches" || record_result FAILED "PostgreSQL major version" "primary=$PG_MAJOR candidate=$REMOTE_MAJOR"; [ "$REMOTE_RECEIVER_STATUS" = streaming ] && record_result PASSED "pg_stat_wal_receiver.status" streaming || record_result FAILED "pg_stat_wal_receiver.status" "${REMOTE_RECEIVER_STATUS:-no row}"; [ "${REMOTE_RECEIVER_SLOT:-}" = "${CANDIDATE_SLOT:-}" ] && record_result PASSED "Replication slot mapping" "slot_name matches" || record_result FAILED "Replication slot mapping" "primary sender slot and candidate receiver slot differ"; [ "$REMOTE_RECOVERY_TARGET_TIMELINE" = latest ] && record_result PASSED recovery_target_timeline latest || record_result FAILED recovery_target_timeline "${REMOTE_RECOVERY_TARGET_TIMELINE:-unknown}"; case "$REMOTE_PAUSE_STATE" in "not paused"|f|false|"") record_result PASSED "WAL Replay state" "not paused";; *) record_result FAILED "WAL Replay state" "$REMOTE_PAUSE_STATE";; esac; case "$REMOTE_DELAY_MS" in ''|*[!0-9]*) record_result WARNING recovery_min_apply_delay "could not determine numeric value";; 0) record_result PASSED recovery_min_apply_delay 0;; *) record_result FAILED recovery_min_apply_delay "${REMOTE_DELAY_MS}ms";; esac
    primary_conninfo_target_crosscheck || true; candidate_downstream_check || true; unselected_standby_check || true; logical_replication_slot_precheck || true; startup_options_guard || true; revalidate_candidate_identity || true
    LOCAL_ARCHIVE_MODE=$(psql_call "SHOW archive_mode" 2>/dev/null|tr -d '[:space:]')||LOCAL_ARCHIVE_MODE=""; LOCAL_ARCHIVE_READY=$(archive_mechanism_configured 2>/dev/null||echo 0); if [ "$LOCAL_ARCHIVE_MODE" != off ]; then if [ "$REMOTE_ARCHIVE_MODE" = off ]; then record_result FAILED archive_mode "current Primary uses archive_mode=$LOCAL_ARCHIVE_MODE but candidate has off"; else record_result PASSED archive_mode "candidate archive_mode=$REMOTE_ARCHIVE_MODE"; fi; if [ "$LOCAL_ARCHIVE_READY" = 1 ] && [ "$REMOTE_ARCHIVE_READY" != 1 ]; then record_result FAILED "archive_command / archive_library" "candidate does not have a configured archiving mechanism"; else record_result PASSED "archive_command / archive_library" "candidate has compatible archiving mechanism configuration"; fi; if [ "$CHECK_ONLY" -eq 1 ]; then record_result "MANUAL CHECK" "Continuous archiving destination" "verify candidate archive destination, credentials, permissions, and duplicate-WAL handling after promotion"; else choose_yes_no "Candidate continuous archiving destination/credentials/permissions are verified" no || fatal_validation "Continuous archiving readiness not confirmed."; fi; else record_result PASSED archive_mode "current Primary archive_mode=off"; fi
    case "${REMOTE_DEFAULT_TX_READ_ONLY:-}" in on|true|t) record_result WARNING default_transaction_read_only "candidate defaults new sessions to read-only after promotion";; *) record_result PASSED default_transaction_read_only "candidate does not default sessions to read-only";; esac
    if [ "$REMOTE_VERSION_NUM" != "$PG_VERSION_NUM" ]; then record_result WARNING "PostgreSQL minor version" "same major but server_version_num differs: primary=$PG_VERSION_NUM candidate=$REMOTE_VERSION_NUM"; else record_result PASSED "PostgreSQL minor version" "$PG_VERSION_NUM matches"; fi
    local_sync=$(psql_call "SHOW synchronous_standby_names" 2>/dev/null | sed -n '1p')||local_sync=""; [ "$local_sync" != "$REMOTE_SYNC_STANDBY_NAMES" ] && record_result WARNING synchronous_standby_names "Primary and candidate policies differ" || record_result PASSED synchronous_standby_names "policy matches"
    rd=$(mktemp_safe) || fatal_validation "Could not create remote disk file."; remote_invoke_file_or_die "$rd" --remote-disk-check "$REMOTE_PGDATA"; while IFS="$TAB" read -r a b c; do [ "$a" = DISK ] || continue; case "$b" in PASSED|WARNING|FAILED|"MANUAL CHECK") record_result "$b" "Remote Disk/WAL risk" "$c";; esac; done < "$rd"
    [ "$RESULT_FAILED" -gt 0 ] && return 1; return 0
}

preconfigure_former_primary() { pfp_conn=$1; pfp_slot=$2; SWITCHOVER_RESTORE_FILE="$STATE_DIR/$STATE_KEY.switchover.restore.sql"; [ ! -e "$SWITCHOVER_RESTORE_FILE" ] || fatal_validation "Existing rollback state exists: $SWITCHOVER_RESTORE_FILE"; ROLLBACK_PRIMARY_CONNINFO=$(psql_call "SELECT setting FROM pg_settings WHERE name='primary_conninfo'" 2>/dev/null|sed -n '1p'); ROLLBACK_PRIMARY_SLOT=$(psql_call "SELECT setting FROM pg_settings WHERE name='primary_slot_name'" 2>/dev/null|sed -n '1p'); ROLLBACK_RECOVERY_TIMELINE=$(psql_call "SELECT setting FROM pg_settings WHERE name='recovery_target_timeline'" 2>/dev/null|sed -n '1p'); psql_call "SELECT 'ALTER SYSTEM SET primary_conninfo = '||quote_literal(setting)||';' FROM pg_settings WHERE name='primary_conninfo'" > "$SWITCHOVER_RESTORE_FILE" || fatal_validation "Could not create rollback state."; psql_call "SELECT 'ALTER SYSTEM SET primary_slot_name = '||quote_literal(setting)||';' FROM pg_settings WHERE name='primary_slot_name'" >> "$SWITCHOVER_RESTORE_FILE" || fatal_validation "Could not create rollback state."; psql_call "SELECT 'ALTER SYSTEM SET recovery_target_timeline = '||quote_literal(setting)||';' FROM pg_settings WHERE name='recovery_target_timeline'" >> "$SWITCHOVER_RESTORE_FILE" || fatal_validation "Could not create rollback state."; chmod 600 "$SWITCHOVER_RESTORE_FILE" 2>/dev/null||true; SWITCHOVER_CONFIG_CHANGED=1; psql_call_var c "$pfp_conn" "ALTER SYSTEM SET primary_conninfo=:'c'" >/dev/null || fatal_validation "Could not stage reverse primary_conninfo."; if [ -n "$pfp_slot" ]; then psql_call_var s "$pfp_slot" "ALTER SYSTEM SET primary_slot_name=:'s'" >/dev/null || fatal_validation "Could not stage primary_slot_name."; else psql_call "ALTER SYSTEM SET primary_slot_name=''" >/dev/null || fatal_validation "Could not stage empty primary_slot_name."; fi; psql_call "ALTER SYSTEM SET recovery_target_timeline='latest'" >/dev/null || fatal_validation "Could not stage recovery_target_timeline."; }
stop_current_primary() { [ -n "$PG_CTL_BIN" ] && [ -x "$PG_CTL_BIN" ] || return 1; "$PG_CTL_BIN" -D "$PGDATA" -m "$SWITCH_SHUTDOWN_MODE" -w stop || return 1; SWITCHOVER_PRIMARY_STOPPED=1; CURRENT_PHASE=after_primary_stop; }
stopped_primary_checkpoint_lsn() { LC_ALL=C "$PG_CONTROLDATA_BIN" "$PGDATA" 2>/dev/null | awk -F: '/Latest checkpoint location/{gsub(/^[ \t]+|[ \t]+$/,"",$2);print $2;exit}'; }
stopped_primary_state() { LC_ALL=C "$PG_CONTROLDATA_BIN" "$PGDATA" 2>/dev/null | awk -F: '/Database cluster state/{sub(/^[ \t]+/,"",$2);print $2;exit}'; }
switchover_shutdown_mode() { section "Shutdown Mode (pg_ctl stop -m)" "현재 Primary를 정상 종료할 PostgreSQL 공식 shutdown mode를 선택합니다."; say "  1. Fast Shutdown (-m fast)"; say "     새 연결을 차단하고 기존 세션을 종료하며 활성 transaction을 rollback 후 정상 종료합니다."; say "  2. Smart Shutdown (-m smart)"; say "     기존 클라이언트가 스스로 연결을 종료할 때까지 기다립니다."; while :; do sm=$(ask "Shutdown mode number" 1) || fatal_usage "Input cancelled."; case "$sm" in 1) SWITCH_SHUTDOWN_MODE=fast;return;;2) SWITCH_SHUTDOWN_MODE=smart;return;;*) say "Enter 1 or 2.";;esac;done; }
conninfo_quote_value() { printf '%s' "$1" | sed "s/\\\\/\\\\\\\\/g;s/'/\\\\'/g"; }
start_former_primary_as_standby() { : > "$PGDATA/standby.signal" || return 1; if [ -n "$POSTMASTER_OPTIONS" ]; then "$PG_CTL_BIN" -D "$PGDATA" -o "$POSTMASTER_OPTIONS" -w start; else "$PG_CTL_BIN" -D "$PGDATA" -w start; fi; }
wait_local_receiver_streaming() { wlrs_timeout=$1; validate_timeout "$wlrs_timeout" "receiver wait" >/dev/null 2>&1 || return 1; wlrs_i=0; while [ "$wlrs_i" -lt "$wlrs_timeout" ]; do wlrs=$(psql_call "SELECT COALESCE(status,'') FROM pg_stat_wal_receiver LIMIT 1" 2>/dev/null|tr -d '[:space:]')||wlrs=""; [ "$wlrs" = streaming ] && return 0; sleep 1; wlrs_i=$((wlrs_i+1)); done; return 1; }
wait_unselected_standbys() { wus_expected=$1; wus_timeout=$2; validate_timeout "$wus_timeout" "downstream wait" >/dev/null 2>&1 || return 1; wus_i=0; while [ "$wus_i" -lt "$wus_timeout" ]; do wus=$(psql_call "SELECT count(*)::text||E'\\t'||count(*) FILTER(WHERE state='streaming')::text FROM pg_stat_replication r WHERE NOT EXISTS (SELECT 1 FROM pg_replication_slots s WHERE s.active_pid=r.pid AND s.slot_type='logical')" 2>/dev/null|sed -n '1p')||wus=""; wus_total=$(printf '%s\n' "$wus"|awk -F '\t' '{print $1}'); wus_stream=$(printf '%s\n' "$wus"|awk -F '\t' '{print $2}'); [ "$wus_total" = "$wus_expected" ] && [ "$wus_stream" = "$wus_expected" ] && return 0; sleep 1; wus_i=$((wus_i+1)); done; return 1; }

planned_switchover() { CURRENT_PHASE=precheck; planned_switchover_precheck || true; if [ "$CHECK_ONLY" -eq 1 ]; then section "Check-only Result" "Planned Switchover 사전검사 결과입니다. PostgreSQL 상태는 변경하지 않았습니다."; show_result_summary; check_only_exit_code; rc=$?; FINAL_EXIT_OVERRIDE=$rc; return "$rc"; fi; show_result_summary; [ "$RESULT_FAILED" -eq 0 ] || fatal_validation "Pre-Switchover validation contains FAILED items."; prepare_state_dir; switchover_shutdown_mode
    np_default=$CANDIDATE_CLIENT; [ "$np_default" = local ] && np_default=""; NEW_PRIMARY_DB_HOST=$(ask "New Primary database host for reverse primary_conninfo" "$np_default") || fatal_usage "Input cancelled."; [ -n "$NEW_PRIMARY_DB_HOST" ] || fatal_usage "New Primary database host is required."; OLD_PRIMARY_APP=$(ask "Former Primary application_name" "$(psql_call "SHOW cluster_name" 2>/dev/null | sed -n '1p')") || fatal_usage "Input cancelled."; [ -n "$OLD_PRIMARY_APP" ] || OLD_PRIMARY_APP=$(hostname 2>/dev/null || echo former_primary)
    ci_h=$(conninfo_quote_value "$NEW_PRIMARY_DB_HOST"); ci_u=$(conninfo_quote_value "$CANDIDATE_REPL_USER"); ci_a=$(conninfo_quote_value "$OLD_PRIMARY_APP"); REVERSE_CONNINFO="host='$ci_h' port='$REMOTE_PORT' user='$ci_u' application_name='$ci_a'"; say "Additional libpq Connection Parameters"; say "  SSL/passfile 등 필요한 libpq 파라미터를 추가합니다. password= 직접 입력은 허용하지 않습니다."; extra=$(ask "Additional connection parameters (empty = none)" "") || fatal_usage "Input cancelled."; if [ -n "$extra" ]; then printf '%s\n' "$extra" | grep -E '(^|[[:space:]])(host|hostaddr|port|user|application_name|password)[[:space:]]*=' >/dev/null 2>&1 && fatal_usage "Additional parameters cannot override host/hostaddr/port/user/application_name or contain password=."; REVERSE_CONNINFO="$REVERSE_CONNINFO $extra"; fi
    REVERSE_SLOT=""; if [ -n "$CANDIDATE_SLOT" ] && choose_yes_no "Create a physical replication slot for former Primary" yes; then REVERSE_SLOT=$(ask "Physical replication slot name" "$(printf '%s_slot' "$OLD_PRIMARY_APP" | tr '[:upper:]' '[:lower:]' | sed 's/[^a-z0-9_]/_/g')") || fatal_usage "Input cancelled."; fi
    confirm_word SWITCHOVER "All automatic checks completed. Next: stage reverse settings and stop current Primary." || fatal_validation "Switchover cancelled."; CURRENT_PHASE=before_primary_stop; preconfigure_former_primary "$REVERSE_CONNINFO" "$REVERSE_SLOT"; revalidate_candidate_identity || fatal_validation "Candidate changed before Primary shutdown."; stop_current_primary || fatal_validation "Could not stop current Primary cleanly."; sd_state=$(stopped_primary_state); sd_lsn=$(stopped_primary_checkpoint_lsn); case "$sd_state" in *"shut down"*) :;; *) fatal_validation "Former Primary is not in clean shutdown state: $sd_state";; esac; [ -n "$sd_lsn" ] || fatal_validation "Could not obtain final checkpoint LSN."
    rw_default=$(remote_invoke --remote-timeout-default "$REMOTE_PGDATA" 2>/dev/null | awk -F '\t' '$1=="TIMEOUT"{print $2}'); case "$rw_default" in ''|*[!0-9]*) rw_default=120;; esac; wait_sec=$(ask "WAL Replay Catch-up Wait seconds" "$rw_default") || fatal_usage "Input cancelled."; validate_timeout "$wait_sec" "Catch-up wait" || fatal_usage "Invalid timeout."; if ! remote_invoke --remote-wait-lsn "$REMOTE_PGDATA" "$sd_lsn" "$wait_sec" >/dev/null 2>&1; then [ "$REMOTE_TRANSPORT" = ssh ] && ! ssh_probe && fatal_remote "SSH failed while waiting for WAL replay catch-up."; fatal_validation "Candidate did not replay through former Primary final checkpoint. Candidate was NOT promoted."; fi; if ! remote_invoke --remote-promote "$REMOTE_PGDATA" >/dev/null 2>&1; then [ "$REMOTE_TRANSPORT" = ssh ] && ! ssh_probe && fatal_remote "SSH failed during promotion."; fatal_validation "Candidate promotion could not be verified."; fi; SWITCHOVER_PROMOTED=1; CURRENT_PHASE=after_promotion
    if [ "$REMOTE_DOWNSTREAM_COUNT" -gt 0 ] 2>/dev/null; then if ! remote_invoke --remote-wait-downstreams "$REMOTE_PGDATA" "$REMOTE_DOWNSTREAM_COUNT" "$rw_default" >/dev/null 2>&1; then [ "$REMOTE_TRANSPORT" = ssh ] && ! ssh_probe && fatal_remote "SSH failed while verifying existing downstream Standbys after promotion."; fatal_validation "Existing downstream Standbys did not all return to pg_stat_replication.state=streaming on the new Primary."; fi; fi
    if [ -n "$REVERSE_SLOT" ]; then if ! remote_invoke --remote-create-slot "$REMOTE_PGDATA" "$REVERSE_SLOT" >/dev/null 2>&1; then [ "$REMOTE_TRANSPORT" = ssh ] && ! ssh_probe && fatal_remote "SSH failed while creating reverse replication slot."; fatal_validation "Could not prepare reverse physical replication slot."; fi; fi
    CURRENT_PHASE=rejoin_old_primary; start_former_primary_as_standby || fatal_validation "Former Primary could not start as Standby."; init_instance_from_pgdata "$PGDATA" 1 || fatal_validation "Former Primary SQL verification failed after restart."; [ "$LOCAL_ROLE" = standby ] || fatal_validation "Former Primary did not enter Standby mode."; verify_timeout=$(psql_call "SELECT CASE WHEN setting::bigint=0 THEN 60 ELSE GREATEST(15,LEAST(300,(setting::bigint/1000)*2)) END FROM pg_settings WHERE name='wal_receiver_timeout'" 2>/dev/null|tr -d '[:space:]')||verify_timeout=60; validate_timeout "$verify_timeout" "receiver verification timeout" >/dev/null 2>&1 || verify_timeout=60; wait_local_receiver_streaming "$verify_timeout" || fatal_validation "Former Primary is Standby but pg_stat_wal_receiver.status did not reach streaming."; if [ "${UNSELECTED_STANDBY_COUNT:-0}" -gt 0 ] 2>/dev/null; then wait_unselected_standbys "$UNSELECTED_STANDBY_COUNT" "$verify_timeout" || fatal_validation "Unselected Standbys did not all reconnect to former Primary after it became Cascading Standby."; fi; np_count=$(remote_invoke --remote-count-standby "$REMOTE_PGDATA" "$OLD_PRIMARY_APP" 2>/dev/null | awk -F '\t' '$1=="COUNT"{print $2;exit}'); case "$np_count" in ''|*[!0-9]*) np_count=0;; esac; [ "$np_count" -eq 1 ] || fatal_validation "New Primary does not show exactly one streaming row for former Primary application_name=$OLD_PRIMARY_APP."; SWITCHOVER_CONFIG_CHANGED=0; rm -f "${SWITCHOVER_RESTORE_FILE:-}" 2>/dev/null || true; CURRENT_PHASE=completed; section "Post-Switchover Verification" "역할 전환이 완료됐습니다."; kv "Former Primary Current Role" "$(current_topology_role 2>/dev/null || echo unknown)"; kv pg_stat_wal_receiver.status "$(psql_call "SELECT status FROM pg_stat_wal_receiver LIMIT 1" 2>/dev/null|sed -n '1p')"; kv "New Primary pg_stat_replication" "$np_count streaming row for $OLD_PRIMARY_APP"; }

pause_wal_replay() { [ "$LOCAL_ROLE" = standby ] || fatal_validation "WAL Replay control requires a Standby."; section "Pause WAL Replay — pg_wal_replay_pause()" "WAL 수신은 유지하고 Standby의 WAL 적용만 일시 중지합니다."; disk_risk_check >/dev/null || true; choose_yes_no "Pause WAL Replay" no || return 0; psql_call "SELECT pg_wal_replay_pause()" >/dev/null || fatal_validation "pg_wal_replay_pause() failed."; }
resume_wal_replay() { [ "$LOCAL_ROLE" = standby ] || fatal_validation "WAL Replay control requires a Standby."; section "Resume WAL Replay — pg_wal_replay_resume()" "일시 중지된 Standby WAL 적용을 다시 시작합니다."; psql_call "SELECT pg_wal_replay_resume()" >/dev/null || fatal_validation "pg_wal_replay_resume() failed."; }
receiver_state_file() { printf '%s/%s.primary_conninfo.restore.sql\n' "$STATE_DIR" "$STATE_KEY"; }
stop_wal_receiver() { [ "$LOCAL_ROLE" = standby ] || fatal_validation "WAL Receiver control requires a Standby."; prepare_state_dir; rs=$(receiver_state_file); [ ! -e "$rs" ] || fatal_validation "Existing WAL Receiver restore state exists: $rs"; psql_call "SELECT 'ALTER SYSTEM SET primary_conninfo='||quote_literal(setting)||';' FROM pg_settings WHERE name='primary_conninfo'" > "$rs" || fatal_validation "Could not save WAL Receiver restore state."; chmod 600 "$rs" 2>/dev/null||true; psql_call "ALTER SYSTEM SET primary_conninfo=''" >/dev/null || fatal_validation "Could not disable primary_conninfo."; if [ "$PG_MAJOR" -eq 12 ]; then "$PG_CTL_BIN" -D "$PGDATA" -m fast -w restart || fatal_validation "PostgreSQL 12 restart failed."; else psql_call "SELECT pg_reload_conf()" >/dev/null || fatal_validation "pg_reload_conf() failed."; fi; }
resume_wal_receiver() { [ "$LOCAL_ROLE" = standby ] || fatal_validation "WAL Receiver control requires a Standby."; prepare_state_dir; rs=$(receiver_state_file); [ -f "$rs" ] || fatal_validation "No saved WAL Receiver restore state: $rs"; psql_call_file "$rs" >/dev/null || fatal_validation "Could not restore primary_conninfo."; if [ "$PG_MAJOR" -eq 12 ]; then "$PG_CTL_BIN" -D "$PGDATA" -m fast -w restart || fatal_validation "PostgreSQL 12 restart failed."; else psql_call "SELECT pg_reload_conf()" >/dev/null || fatal_validation "pg_reload_conf() failed."; fi; rm -f "$rs" 2>/dev/null||true; }
replication_status() { topology_discovery; section "Replication Status" "공식 통계 뷰와 설정을 사용해 Streaming Replication 상태를 확인합니다."; if [ "$LOCAL_ROLE" = primary ]; then psql_call "SELECT application_name||' | client='||COALESCE(client_addr::text,'local')||' | state='||state||' | sync_state='||sync_state||' | replay_lsn='||COALESCE(replay_lsn::text,'') FROM pg_stat_replication ORDER BY application_name,pid" | sed 's/^/  /'; else psql_call "SELECT 'status='||status||' | sender_host='||COALESCE(sender_host,'')||' | sender_port='||sender_port||' | slot_name='||COALESCE(slot_name,'') FROM pg_stat_wal_receiver" | sed 's/^/  /'; kv "WAL Replay state" "$(pause_state 2>/dev/null || echo unknown)"; fi; disk_risk_check >/dev/null || true; }
main_menu() { while :; do LOCAL_ROLE=$(psql_call "SELECT CASE WHEN pg_is_in_recovery() THEN 'standby' ELSE 'primary' END" 2>/dev/null | tr -d '[:space:]') || fatal_validation "Could not refresh role."; section "PostgreSQL Physical Replication Control" "공식 용어를 기준으로 현재 역할에서 실행 가능한 작업을 표시합니다."; kv "Current Role" "$(current_topology_role 2>/dev/null || echo unknown)"; if [ "$LOCAL_ROLE" = primary ]; then say "  1. Planned Switchover"; say "     정상 Primary와 선택한 Direct Standby의 역할을 계획적으로 전환합니다."; say "  2. Replication Status"; say "     pg_stat_replication, replication slot, WAL/디스크 위험을 확인합니다."; say "  3. Exit"; mc=$(ask "Select operation" 2)||exit 0; case "$mc" in 1) RESULT_PASSED=0;RESULT_WARNING=0;RESULT_FAILED=0;RESULT_MANUAL=0;planned_switchover;;2)replication_status;;3)exit 0;;*)say "Invalid selection.";;esac; else say "  1. Pause WAL Replay — pg_wal_replay_pause()"; say "     WAL 수신은 유지하고 WAL 적용만 중지합니다."; say "  2. Resume WAL Replay — pg_wal_replay_resume()"; say "     일시 중지된 WAL 적용을 다시 시작합니다."; say "  3. Disable WAL Receiver Streaming — primary_conninfo / WAL Receiver"; say "     Upstream과의 Streaming Replication 연결을 중지합니다."; say "  4. Restore WAL Receiver Streaming — primary_conninfo / WAL Receiver"; say "     저장한 primary_conninfo를 복원해 Streaming Replication을 재연결합니다."; say "  5. Replication Status"; say "     pg_stat_wal_receiver, Cascading Replication, WAL/디스크 위험을 확인합니다."; say "  6. Exit"; mc=$(ask "Select operation" 5)||exit 0; case "$mc" in 1)pause_wal_replay;;2)resume_wal_replay;;3)stop_wal_receiver;;4)resume_wal_receiver;;5)replication_status;;6)exit 0;;*)say "Invalid selection.";;esac; fi; done; }

remote_reset_globals() { PGPORT=""; SOCKET_DIR=""; PSQL_BIN=""; PG_CTL_BIN=""; PG_CONTROLDATA_BIN=""; DB_NAME=""; PGUSER_LOCAL="${PGUSER:-}"; }
remote_init_exact() { remote_reset_globals; init_instance_from_pgdata "$1" 1 >/dev/null 2>&1 || exit "$EX_VALIDATION"; }
remote_list() { exp=$1; t=$(mktemp_safe)||exit "$EX_VALIDATION"; saved=${PGDATA:-}; PGDATA=""; discover_pgdata_candidates > "$t"; PGDATA=$saved; while IFS= read -r p; do [ -n "$p" ]||continue; remote_reset_globals; if init_instance_from_pgdata "$p" 1 >/dev/null 2>&1; then [ "$SYSTEM_IDENTIFIER" = "$exp" ] && [ "$LOCAL_ROLE" = standby ] || continue; wr=$(psql_call "SELECT COALESCE(sender_host,'')||E'\\t'||COALESCE(sender_port::text,'')||E'\\t'||COALESCE(status,'')||E'\\t'||COALESCE(slot_name,'') FROM pg_stat_wal_receiver LIMIT 1" 2>/dev/null|sed -n '1p'); shost=$(printf '%s\n' "$wr"|awk -F '\t' '{print $1}'); sport=$(printf '%s\n' "$wr"|awk -F '\t' '{print $2}'); wstat=$(printf '%s\n' "$wr"|awk -F '\t' '{print $3}'); wslot=$(printf '%s\n' "$wr"|awk -F '\t' '{print $4}'); replay=$(psql_call "SELECT COALESCE(pg_last_wal_replay_lsn()::text,'')" 2>/dev/null|sed -n '1p'); pst=$(pause_state 2>/dev/null||echo unknown); delay=$(psql_call "SELECT setting FROM pg_settings WHERE name='recovery_min_apply_delay'" 2>/dev/null|tr -d '[:space:]'); sync=$(psql_call "SHOW synchronous_standby_names" 2>/dev/null|tr '\t\r\n' '   '); defro=$(psql_call "SHOW default_transaction_read_only" 2>/dev/null|tr -d '[:space:]'); arch=$(psql_call "SHOW archive_mode" 2>/dev/null|tr -d '[:space:]'); archready=$(archive_mechanism_configured 2>/dev/null||echo 0); down=$(psql_call "SELECT count(*) FROM pg_stat_replication r WHERE NOT EXISTS (SELECT 1 FROM pg_replication_slots s WHERE s.active_pid=r.pid AND s.slot_type='logical')" 2>/dev/null|tr -d '[:space:]'); [ "$down" -gt 0 ] 2>/dev/null && topo="Cascading Standby" || topo="Standby"; tl=$(psql_call "SHOW recovery_target_timeline" 2>/dev/null|tr -d '[:space:]'); printf 'INSTANCE\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\n' "$PGDATA" "$PGPORT" "$PG_VERSION_NUM" "$LOCAL_ROLE" "$SYSTEM_IDENTIFIER" "$shost" "$sport" "$replay" "$pst" "$delay" "$wstat" "$sync" "$defro" "$arch" "$archready" "$topo" "$down" "$tl" "$wslot"; fi; done < "$t"; }
remote_env_check() { remote_init_exact "$1"; r_user=$(id -un 2>/dev/null||echo ""); r_owner=$(ps -o user= -p "$POSTMASTER_PID" 2>/dev/null|awk '{print $1;exit}'); r_path=${PATH:-}; r_exec=0; [ -n "$PG_CTL_BIN" ] && [ -x "$PG_CTL_BIN" ] && r_exec=1; printf 'ENV\t%s\t%s\t%s\t%s\t%s\n' "$r_user" "$r_owner" "$r_path" "${PG_CTL_BIN:-}" "$r_exec"; }
remote_config_write_check() { remote_init_exact "$1"; derive_state_paths; if [ -e "$AUTO_CONF" ]; then [ -w "$AUTO_CONF" ] && printf 'CHECK\tpostgresql.auto.conf permission\tPASS:writable\n' || printf 'CHECK\tpostgresql.auto.conf permission\tFAIL:not writable\n'; else [ -w "$PGDATA" ] && printf 'CHECK\tpostgresql.auto.conf permission\tPASS:data_directory permits creation\n' || printf 'CHECK\tpostgresql.auto.conf permission\tFAIL:data_directory not writable\n'; fi; if [ -e "$PGDATA/standby.signal" ]; then [ -w "$PGDATA/standby.signal" ] && printf 'CHECK\tstandby.signal permission\tPASS:existing file writable\n' || printf 'CHECK\tstandby.signal permission\tFAIL:existing file not writable\n'; else [ -w "$PGDATA" ] && printf 'CHECK\tstandby.signal permission\tPASS:data_directory permits creation\n' || printf 'CHECK\tstandby.signal permission\tFAIL:data_directory not writable\n'; fi; if [ -d "$STATE_DIR" ]; then par=$STATE_DIR; else par=$(nearest_existing_parent "$STATE_DIR"); fi; [ -d "$par" ] && [ -w "$par" ] && printf 'CHECK\tstate directory permission\tPASS:existing parent writable\n' || printf 'CHECK\tstate directory permission\tFAIL:existing parent not writable\n'; }
remote_disk_check() { remote_init_exact "$1"; d=$(df -Pk "$PGDATA" 2>/dev/null|awk 'NR==2{print $4" kB free, used="$5}'); [ -n "$d" ] || { printf 'DISK\tFAILED\tdf failed for candidate data_directory\n'; return 1; }; if [ "$LOCAL_ROLE" = standby ]; then p=$(pause_state 2>/dev/null||echo unknown); b=$(psql_call "SELECT COALESCE(pg_wal_lsn_diff(pg_last_wal_receive_lsn(),pg_last_wal_replay_lsn())::bigint,0)" 2>/dev/null|tr -d '[:space:]')||b=unknown; case "$p" in "not paused"|f|false) printf 'DISK\tPASSED\t%s; replay not paused; backlog_bytes=%s\n' "$d" "$b";; *) printf 'DISK\tWARNING\t%s; replay_state=%s; backlog_bytes=%s; received WAL can accumulate\n' "$d" "$p" "$b";; esac; else printf 'DISK\tPASSED\t%s\n' "$d"; fi; }
remote_probe_upstream() { remote_init_exact "$1"; probe_user=$2; wr=$(psql_call "SELECT COALESCE(sender_host,'')||E'\\t'||COALESCE(sender_port::text,'') FROM pg_stat_wal_receiver LIMIT 1" 2>/dev/null|sed -n '1p'); ph=$(printf '%s\n' "$wr"|awk -F '\t' '{print $1}'); pp=$(printf '%s\n' "$wr"|awk -F '\t' '{print $2}'); [ -n "$ph" ] && [ -n "$pp" ] || exit "$EX_VALIDATION"; for pdb in postgres template1; do out=$("$PSQL_BIN" -X -q -A -t -v ON_ERROR_STOP=1 -h "$ph" -p "$pp" -U "$probe_user" -d "$pdb" -c "SELECT system_identifier::text||E'\\t'||current_setting('port')||E'\\t'||CASE WHEN pg_is_in_recovery() THEN 'standby' ELSE 'primary' END FROM pg_control_system()" 2>/dev/null) && { printf 'UPSTREAM\t%s\n' "$out"; return 0; }; done; return "$EX_VALIDATION"; }
remote_downstreams() { remote_init_exact "$1"; psql_call "SELECT 'DOWNSTREAM'||E'\\t'||application_name||E'\\t'||COALESCE(client_addr::text,'local')||E'\\t'||state||E'\\t'||sync_state||E'\\t'||COALESCE(replay_lsn::text,'')||E'\\t'||COALESCE((SELECT slot_name FROM pg_replication_slots s WHERE s.active_pid=r.pid AND s.slot_type='physical' LIMIT 1),'') FROM pg_stat_replication r WHERE NOT EXISTS (SELECT 1 FROM pg_replication_slots s WHERE s.active_pid=r.pid AND s.slot_type='logical') ORDER BY application_name,client_addr NULLS FIRST,pid"; }
remote_list_downstream() { rld_sysid=$1; rld_sender_port=$2; rld_slot_expected=$3; rld_tmp=$(mktemp_safe)||exit "$EX_VALIDATION"; rld_saved=${PGDATA:-}; PGDATA=""; discover_pgdata_candidates > "$rld_tmp"; PGDATA=$rld_saved; while IFS= read -r rld_pg; do [ -n "$rld_pg" ] || continue; remote_reset_globals; if init_instance_from_pgdata "$rld_pg" 1 >/dev/null 2>&1; then [ "$SYSTEM_IDENTIFIER" = "$rld_sysid" ] && [ "$LOCAL_ROLE" = standby ] || continue; rld_wr=$(psql_call "SELECT COALESCE(sender_host,'')||E'\\t'||COALESCE(sender_port::text,'')||E'\\t'||COALESCE(status,'')||E'\\t'||COALESCE(slot_name,'') FROM pg_stat_wal_receiver LIMIT 1" 2>/dev/null|sed -n '1p'); rld_host=$(printf '%s\n' "$rld_wr"|awk -F '\t' '{print $1}'); rld_port=$(printf '%s\n' "$rld_wr"|awk -F '\t' '{print $2}'); rld_status=$(printf '%s\n' "$rld_wr"|awk -F '\t' '{print $3}'); rld_slot=$(printf '%s\n' "$rld_wr"|awk -F '\t' '{print $4}'); [ "$rld_port" = "$rld_sender_port" ] || continue; [ "$rld_status" = streaming ] || continue; [ "$rld_slot" = "$rld_slot_expected" ] || continue; rld_tl=$(psql_call "SHOW recovery_target_timeline" 2>/dev/null|tr -d '[:space:]'); printf 'DOWNSTREAM_INSTANCE\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\n' "$PGDATA" "$PGPORT" "$PG_VERSION_NUM" "$SYSTEM_IDENTIFIER" "$rld_host" "$rld_port" "$rld_status" "$rld_tl" "$rld_slot"; fi; done < "$rld_tmp"; }
remote_check_logical_slot() { remote_init_exact "$1"; rcls_slot=$2; [ "$PG_MAJOR" -ge 17 ] || exit "$EX_VALIDATION"; rcls=$(psql_call_var s "$rcls_slot" "SELECT CASE WHEN EXISTS(SELECT 1 FROM pg_replication_slots WHERE slot_name=:'s' AND slot_type='logical' AND synced AND NOT temporary AND invalidation_reason IS NULL) THEN 1 ELSE 0 END" 2>/dev/null|tr -d '[:space:]') || exit "$EX_VALIDATION"; [ "$rcls" = 1 ] || exit "$EX_VALIDATION"; printf 'LOGICAL_SLOT\t%s\tready\n' "$rcls_slot"; }
remote_validate_candidate() { rvc_pg=$1; rvc_sys=$2; rvc_sender_port=$3; rvc_slot=$4; rvc_down_expected=$5; remote_init_exact "$rvc_pg"; [ "$LOCAL_ROLE" = standby ] || exit "$EX_VALIDATION"; [ "$SYSTEM_IDENTIFIER" = "$rvc_sys" ] || exit "$EX_VALIDATION"; rvc_wr=$(psql_call "SELECT COALESCE(status,'')||E'\\t'||COALESCE(sender_port::text,'')||E'\\t'||COALESCE(slot_name,'') FROM pg_stat_wal_receiver LIMIT 1" 2>/dev/null|sed -n '1p') || exit "$EX_VALIDATION"; [ "$(printf '%s\n' "$rvc_wr"|awk -F '\t' '{print $1}')" = streaming ] || exit "$EX_VALIDATION"; [ "$(printf '%s\n' "$rvc_wr"|awk -F '\t' '{print $2}')" = "$rvc_sender_port" ] || exit "$EX_VALIDATION"; [ "$(printf '%s\n' "$rvc_wr"|awk -F '\t' '{print $3}')" = "$rvc_slot" ] || exit "$EX_VALIDATION"; rvc_pause=$(pause_state 2>/dev/null||echo unknown); case "$rvc_pause" in "not paused"|f|false) ;; *) exit "$EX_VALIDATION";; esac; rvc_delay=$(psql_call "SELECT setting FROM pg_settings WHERE name='recovery_min_apply_delay'" 2>/dev/null|tr -d '[:space:]') || exit "$EX_VALIDATION"; [ "$rvc_delay" = 0 ] || exit "$EX_VALIDATION"; rvc_tl=$(psql_call "SHOW recovery_target_timeline" 2>/dev/null|tr -d '[:space:]') || exit "$EX_VALIDATION"; [ "$rvc_tl" = latest ] || exit "$EX_VALIDATION"; rvc_down=$(psql_call "SELECT count(*) FROM pg_stat_replication r WHERE NOT EXISTS (SELECT 1 FROM pg_replication_slots s WHERE s.active_pid=r.pid AND s.slot_type='logical')" 2>/dev/null|tr -d '[:space:]') || exit "$EX_VALIDATION"; [ "$rvc_down" = "$rvc_down_expected" ] || exit "$EX_VALIDATION"; rvc_bad=$(psql_call "SELECT count(*) FROM pg_stat_replication r WHERE state<>'streaming' AND NOT EXISTS (SELECT 1 FROM pg_replication_slots s WHERE s.active_pid=r.pid AND s.slot_type='logical')" 2>/dev/null|tr -d '[:space:]') || exit "$EX_VALIDATION"; [ "$rvc_bad" = 0 ] || exit "$EX_VALIDATION"; printf 'CANDIDATE_READY\t%s\n' "$rvc_pg"; }
remote_wait_downstreams() { rwd_pg=$1; rwd_expected=$2; rwd_timeout=$3; remote_init_exact "$rwd_pg"; validate_timeout "$rwd_timeout" timeout >/dev/null 2>&1 || exit "$EX_USAGE"; rwd_i=0; while [ "$rwd_i" -lt "$rwd_timeout" ]; do rwd=$(psql_call "SELECT count(*)::text||E'\\t'||count(*) FILTER(WHERE state='streaming')::text FROM pg_stat_replication r WHERE NOT EXISTS (SELECT 1 FROM pg_replication_slots s WHERE s.active_pid=r.pid AND s.slot_type='logical')" 2>/dev/null|sed -n '1p')||rwd=""; rwd_total=$(printf '%s\n' "$rwd"|awk -F '\t' '{print $1}'); rwd_stream=$(printf '%s\n' "$rwd"|awk -F '\t' '{print $2}'); [ "$rwd_total" = "$rwd_expected" ] && [ "$rwd_stream" = "$rwd_expected" ] && return 0; sleep 1; rwd_i=$((rwd_i+1)); done; return "$EX_VALIDATION"; }
remote_lock_path() { remote_init_exact "$1"; derive_state_paths; printf '%s\n' "$LOCAL_LOCK_DIR"; }
remote_lock_acquire() { p=$1;t=$2; lp=$(remote_lock_path "$p") || exit "$EX_VALIDATION"; if mkdir "$lp" 2>/dev/null; then printf '%s\n' "$t" > "$lp/token"; chmod 700 "$lp" 2>/dev/null||true; printf 'LOCKED\t%s\n' "$lp"; return 0; fi; return "$EX_VALIDATION"; }
remote_lock_release() { p=$1;t=$2; lp=$(remote_lock_path "$p") || exit "$EX_VALIDATION"; [ -f "$lp/token" ] || return 0; have=$(sed -n '1p' "$lp/token" 2>/dev/null); [ "$have" = "$t" ] || exit "$EX_VALIDATION"; rm -f "$lp/token" 2>/dev/null||true; rmdir "$lp" 2>/dev/null||true; }
remote_timeout_default() { remote_init_exact "$1"; x=$(psql_call "SELECT CASE WHEN setting::bigint=0 THEN 120 ELSE GREATEST(30,LEAST(600,(setting::bigint/1000)*2)) END FROM pg_settings WHERE name='wal_receiver_timeout'" 2>/dev/null|tr -d '[:space:]')||x=120; validate_timeout "$x" "remote timeout" >/dev/null 2>&1 || x=120; printf 'TIMEOUT\t%s\n' "$x"; }
remote_wait_lsn() { remote_init_exact "$1"; target=$2; timeout=$3; validate_timeout "$timeout" timeout >/dev/null 2>&1 || exit "$EX_USAGE"; i=0; while [ "$i" -lt "$timeout" ]; do ok=$(psql_call_var t "$target" "SELECT CASE WHEN pg_last_wal_replay_lsn()>=:'t'::pg_lsn THEN 1 ELSE 0 END" 2>/dev/null|tr -d '[:space:]')||ok=0; [ "$ok" = 1 ] && return 0; sleep 1;i=$((i+1)); done; return "$EX_VALIDATION"; }
remote_promote() { remote_init_exact "$1"; [ "$LOCAL_ROLE" = standby ] || exit "$EX_VALIDATION"; psql_call "SELECT pg_promote(true,60)" 2>/dev/null|grep -E '^(t|true)$' >/dev/null || exit "$EX_VALIDATION"; }
remote_create_slot() { remote_init_exact "$1"; s=$2; [ "$LOCAL_ROLE" = primary ] || exit "$EX_VALIDATION"; e=$(psql_call_var s "$s" "SELECT count(*) FROM pg_replication_slots WHERE slot_name=:'s' AND slot_type='physical'" 2>/dev/null|tr -d '[:space:]')||exit "$EX_VALIDATION"; [ "$e" -gt 0 ] 2>/dev/null || psql_call_var s "$s" "SELECT pg_create_physical_replication_slot(:'s')" >/dev/null || exit "$EX_VALIDATION"; }
remote_count_standby() { remote_init_exact "$1"; app=$2; c=$(psql_call_var a "$app" "SELECT count(*) FROM pg_stat_replication r WHERE application_name=:'a' AND state='streaming' AND NOT EXISTS (SELECT 1 FROM pg_replication_slots s WHERE s.active_pid=r.pid AND s.slot_type='logical')" 2>/dev/null|tr -d '[:space:]')||c=0; printf 'COUNT\t%s\n' "$c"; }

case "${1:-}" in
    --remote-list) [ "$#" -eq 2 ] || exit "$EX_USAGE"; INTERNAL_MODE=1; remote_list "$2"; exit $? ;;
    --remote-env-check) [ "$#" -eq 2 ] || exit "$EX_USAGE"; INTERNAL_MODE=1; remote_env_check "$2"; exit $? ;;
    --remote-config-write-check) [ "$#" -eq 2 ] || exit "$EX_USAGE"; INTERNAL_MODE=1; remote_config_write_check "$2"; exit $? ;;
    --remote-disk-check) [ "$#" -eq 2 ] || exit "$EX_USAGE"; INTERNAL_MODE=1; remote_disk_check "$2"; exit $? ;;
    --remote-probe-upstream) [ "$#" -eq 3 ] || exit "$EX_USAGE"; INTERNAL_MODE=1; remote_probe_upstream "$2" "$3"; exit $? ;;
    --remote-downstreams) [ "$#" -eq 2 ] || exit "$EX_USAGE"; INTERNAL_MODE=1; remote_downstreams "$2"; exit $? ;;
    --remote-list-downstream) [ "$#" -eq 4 ] || exit "$EX_USAGE"; INTERNAL_MODE=1; remote_list_downstream "$2" "$3" "$4"; exit $? ;;
    --remote-check-logical-slot) [ "$#" -eq 3 ] || exit "$EX_USAGE"; INTERNAL_MODE=1; remote_check_logical_slot "$2" "$3"; exit $? ;;
    --remote-validate-candidate) [ "$#" -eq 6 ] || exit "$EX_USAGE"; INTERNAL_MODE=1; remote_validate_candidate "$2" "$3" "$4" "$5" "$6"; exit $? ;;
    --remote-wait-downstreams) [ "$#" -eq 4 ] || exit "$EX_USAGE"; INTERNAL_MODE=1; remote_wait_downstreams "$2" "$3" "$4"; exit $? ;;
    --remote-lock-acquire) [ "$#" -eq 3 ] || exit "$EX_USAGE"; INTERNAL_MODE=1; remote_lock_acquire "$2" "$3"; exit $? ;;
    --remote-lock-release) [ "$#" -eq 3 ] || exit "$EX_USAGE"; INTERNAL_MODE=1; remote_lock_release "$2" "$3"; exit $? ;;
    --remote-timeout-default) [ "$#" -eq 2 ] || exit "$EX_USAGE"; INTERNAL_MODE=1; remote_timeout_default "$2"; exit $? ;;
    --remote-wait-lsn) [ "$#" -eq 4 ] || exit "$EX_USAGE"; INTERNAL_MODE=1; remote_wait_lsn "$2" "$3" "$4"; exit $? ;;
    --remote-promote) [ "$#" -eq 2 ] || exit "$EX_USAGE"; INTERNAL_MODE=1; remote_promote "$2"; exit $? ;;
    --remote-create-slot) [ "$#" -eq 3 ] || exit "$EX_USAGE"; INTERNAL_MODE=1; remote_create_slot "$2" "$3"; exit $? ;;
    --remote-count-standby) [ "$#" -eq 3 ] || exit "$EX_USAGE"; INTERNAL_MODE=1; remote_count_standby "$2" "$3"; exit $? ;;
esac
case "$#" in
    0) ;;
    1) case "$1" in --check-only) CHECK_ONLY=1 ;; --help|-h) usage; exit "$EX_OK" ;; *) fatal_usage "Unknown option: $1" ;; esac ;;
    *) fatal_usage "Options cannot be combined. Public mode accepts only --check-only." ;;
esac
say "PostgreSQL Physical Replication Control / Planned Switchover v$SCRIPT_VERSION"
say "  PostgreSQL 12~18 | POSIX /bin/sh | no external HA-manager dependency"
[ "$CHECK_ONLY" -eq 1 ] && report_init || true
select_local_instance
[ "$CHECK_ONLY" -eq 1 ] && report_instance_metadata
derive_state_paths
acquire_local_lock
show_instance_summary
topology_discovery
if [ "$CHECK_ONLY" -eq 1 ]; then planned_switchover; rc=$?; FINAL_EXIT_OVERRIDE=$rc; exit "$rc"; else main_menu; fi
